const config = {
  "previewFeatures": [],
  "clientVersion": "7.7.0",
  "engineVersion": "75cbdc1eb7150937890ad5465d861175c6624711",
  "activeProvider": "postgresql",
  "inlineSchema": "// ============================================================\n// AUTO-GENERATED — do not edit manually.\n// Run `bun run prisma:combine` to regenerate from prisma/schema/*.prisma\n// ============================================================\n\n// --- base.prisma ---\ndatasource db {\n  provider = \"postgresql\"\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/prisma/client\"\n}\n\n// --- ai-config.prisma ---\nenum AIProvider {\n  openai\n  anthropic\n  bedrock\n  openrouter\n  // LiteLLM is an OpenAI-API-compatible proxy. Two distinct uses:\n  //   1. Bring-your-own (core/free): operator stands up LiteLLM and\n  //      points org rows at it via baseUrl + a virtual key in apiKey.\n  //   2. Trustalo-managed (EE): SaaS deployment forces routing through\n  //      Trustalo's hosted proxy with a per-tenant virtual key for\n  //      metered billing. See packages/billing.ee and the\n  //      TenantLiteLLMKey / CreditWallet / LiteLLMSpendEvent tables in\n  //      billing.ee.prisma.\n  litellm\n}\n\nenum AIFeature {\n  quiz_generation\n  risk_analysis\n  policy_drafting\n  policy_generation\n  vendor_assessment\n  incident_summary\n  control_suggestion\n  automated_check_generation\n  risk_scoring\n  vendor_scoring\n  questionnaire_answering\n  trust_center_summary\n  // Phase 1 of \"ongoing AI context\": LLM extracts structured fact\n  // proposals from a paragraph of pasted text (or any other text\n  // source). Always advisory — output lands in\n  // TenantContextProposal until a human accepts.\n  context_extraction\n  // Phase 2 of \"ongoing AI context\": general compliance assistant\n  // chat. Streams grounded answers using TenantContext +\n  // policies/risks/vendors/controls/frameworks; passively extracts\n  // new context proposals in parallel via context_extraction.\n  chat_assistant\n  // Per-control evidence agent: an LLM-driven loop in the collector\n  // that follows natural-language instructions and calls integration\n  // provider capabilities as tools to gather audit-grade evidence.\n  evidence_agent\n  // Vendor research deep-dive (collector). Previously bypassed\n  // resolveOrgAI with a direct OpenAI SDK call; now routed through the\n  // resolver so it is metered like every other LLM feature.\n  vendor_research\n}\n\nmodel AIProviderConfig {\n  id              String     @id @default(cuid())\n  tenantId        String\n  provider        AIProvider\n  apiKey          String?\n  region          String?\n  accessKeyId     String?\n  secretAccessKey String?\n  baseUrl         String?\n  isEnabled       Boolean    @default(true)\n  createdAt       DateTime   @default(now())\n  updatedAt       DateTime   @updatedAt\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@unique([tenantId, provider])\n  @@index([tenantId])\n}\n\nmodel AIFeatureConfig {\n  id        String     @id @default(cuid())\n  tenantId  String\n  feature   AIFeature\n  provider  AIProvider\n  model     String\n  isEnabled Boolean    @default(true)\n  createdAt DateTime   @default(now())\n  updatedAt DateTime   @updatedAt\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@unique([tenantId, feature])\n  @@index([tenantId])\n}\n\n// --- ai-governance.prisma ---\nenum AISystemType {\n  machine_learning\n  deep_learning\n  nlp\n  computer_vision\n  generative_ai\n  other\n}\n\nenum AILifecycleStage {\n  design\n  development\n  testing\n  deployment\n  monitoring\n  decommissioned\n}\n\nenum AIRiskLevel {\n  minimal\n  limited\n  high\n  unacceptable\n}\n\nenum RiskRating {\n  low\n  medium\n  high\n}\n\nenum AIImpactStatus {\n  pending\n  in_review\n  approved\n  rejected\n}\n\n// Lifecycle for a structured risk assessment. Mirrors the BIA / policy\n// approval flow so reviewers see a familiar pattern across the app.\nenum AIRiskAssessmentStatus {\n  draft\n  in_progress\n  completed\n  approved\n}\n\n// Operational AI incidents. Categories follow EU AI Act Art. 73 reporting\n// taxonomy + NIST AI RMF MANAGE-4 incident types.\nenum AIIncidentSeverity {\n  low\n  medium\n  high\n  critical\n}\n\nenum AIIncidentCategory {\n  bias\n  drift\n  hallucination\n  accuracy\n  privacy\n  security\n  safety\n  misuse\n  availability\n  other\n}\n\nenum AIIncidentStatus {\n  open\n  investigating\n  mitigated\n  resolved\n  closed\n}\n\nmodel AISystem {\n  id             String           @id @default(cuid())\n  tenantId       String\n  name           String\n  description    String?\n  purpose        String?\n  type           AISystemType\n  lifecycleStage AILifecycleStage @default(design)\n  riskLevel      AIRiskLevel      @default(minimal)\n  dataTypes      String[]\n  ownerId        String?\n  createdAt      DateTime         @default(now())\n  updatedAt      DateTime         @updatedAt\n\n  tenant            Tenant               @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  owner             User?                @relation(\"AISystemOwner\", fields: [ownerId], references: [id])\n  riskAssessments   AIRiskAssessment[]\n  impactAssessments AIImpactAssessment[]\n  incidents         AIIncident[]\n\n  @@index([tenantId])\n}\n\nmodel AIRiskAssessment {\n  id           String @id @default(cuid())\n  aiSystemId   String\n  tenantId     String\n  assessedById String\n\n  // Optional human-readable title — useful when an AI system has multiple\n  // concurrent assessments (e.g. quarterly re-assessment cycles).\n  title       String?\n  // Methodology / framework used. Free-form so orgs can plug their own,\n  // with EU AI Act / NIST / ISO as the well-known starters.\n  methodology String?\n\n  biasRisk     RiskRating\n  privacyRisk  RiskRating\n  safetyRisk   RiskRating\n  securityRisk RiskRating\n  misuseRisk   RiskRating\n  // Computed-or-overridden overall rating. Defaults to the max of the\n  // component ratings on the API side; explicit field lets reviewers override.\n  overallRisk  RiskRating?\n\n  mitigationPlan String?\n  // Residual risk after mitigations are applied — what regulators ask for.\n  residualRisk   RiskRating?\n\n  status       AIRiskAssessmentStatus @default(draft)\n  approvedById String?\n  approvedAt   DateTime?\n\n  assessedAt     DateTime  @default(now())\n  nextReviewDate DateTime?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  aiSystem   AISystem @relation(fields: [aiSystemId], references: [id], onDelete: Cascade)\n  tenant     Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  assessedBy User     @relation(\"AIRiskAssessor\", fields: [assessedById], references: [id])\n  approvedBy User?    @relation(\"AIRiskApprover\", fields: [approvedById], references: [id])\n\n  @@index([tenantId])\n  @@index([aiSystemId])\n  @@index([status])\n  @@index([nextReviewDate])\n}\n\nmodel AIIncident {\n  id       String @id @default(cuid())\n  tenantId String\n\n  // An incident is always rooted in a specific AI system. Use cases live\n  // on the system itself (per the consolidation decision: AISystem is the\n  // unit of governance in this MVP).\n  aiSystemId String\n\n  title       String\n  description String?\n  category    AIIncidentCategory\n  severity    AIIncidentSeverity\n  status      AIIncidentStatus   @default(open)\n\n  // Timeline.\n  detectedAt DateTime  @default(now())\n  reportedAt DateTime  @default(now())\n  resolvedAt DateTime?\n\n  // Investigation.\n  rootCause                    String?\n  remediation                  String?\n  // For incidents that require external (regulator / customer) notification,\n  // capture that we did so. Enough granularity for v1; a structured\n  // notification log is a clean follow-up.\n  externalNotificationRequired Boolean   @default(false)\n  externalNotificationSentAt   DateTime?\n\n  reportedById String?\n  assigneeId   String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tenant     Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  aiSystem   AISystem @relation(fields: [aiSystemId], references: [id], onDelete: Cascade)\n  reportedBy User?    @relation(\"AIIncidentReporter\", fields: [reportedById], references: [id])\n  assignee   User?    @relation(\"AIIncidentAssignee\", fields: [assigneeId], references: [id])\n\n  @@index([tenantId])\n  @@index([aiSystemId])\n  @@index([status])\n  @@index([severity])\n  @@index([detectedAt])\n}\n\nmodel AIImpactAssessment {\n  id                     String         @id @default(cuid())\n  aiSystemId             String\n  tenantId               String\n  assessedById           String\n  societalImpact         String?\n  ethicalConsiderations  String?\n  environmentalImpact    String?\n  humanOversightMeasures String?\n  transparencyMeasures   String?\n  status                 AIImpactStatus @default(pending)\n  approvedById           String?\n  approvedAt             DateTime?\n  createdAt              DateTime       @default(now())\n\n  aiSystem   AISystem @relation(fields: [aiSystemId], references: [id], onDelete: Cascade)\n  tenant     Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  assessedBy User     @relation(\"AIImpactAssessor\", fields: [assessedById], references: [id])\n  approvedBy User?    @relation(\"AIImpactApprover\", fields: [approvedById], references: [id])\n\n  @@index([tenantId])\n  @@index([aiSystemId])\n}\n\n// --- asset.prisma ---\nenum AssetType {\n  hardware\n  software\n  data\n  service\n  personnel\n  facility\n  cloud_resource\n}\n\nenum AssetClassification {\n  public\n  internal\n  confidential\n  restricted\n}\n\nenum AssetStatus {\n  active\n  decommissioned\n  under_review\n}\n\nmodel Asset {\n  id             String              @id @default(cuid())\n  tenantId       String\n  name           String\n  description    String?\n  type           AssetType\n  classification AssetClassification @default(internal)\n  ownerId        String?\n  deletedById    String?\n  deletedAt      DateTime?\n  location       String?\n  status         AssetStatus         @default(active)\n  metadata       Json?\n  createdAt      DateTime            @default(now())\n  updatedAt      DateTime            @updatedAt\n\n  tenant    Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  owner     User?  @relation(\"AssetOwner\", fields: [ownerId], references: [id])\n  deletedBy User?  @relation(\"AssetDeletedBy\", fields: [deletedById], references: [id])\n\n  @@index([tenantId])\n  @@index([tenantId, deletedAt, createdAt])\n  @@index([tenantId, status, deletedAt])\n}\n\n// --- audit.prisma ---\nenum AuditType {\n  internal\n  external\n  certification\n}\n\nenum AuditStatus {\n  planned\n  in_progress\n  completed\n  cancelled\n}\n\nenum AuditFindingSeverity {\n  critical\n  major\n  minor\n  observation\n  opportunity\n}\n\nenum AuditFindingStatus {\n  open\n  in_progress\n  remediated\n  verified\n  closed\n}\n\nmodel Audit {\n  id                  String      @id @default(cuid())\n  tenantId            String\n  title               String\n  description         String?\n  type                AuditType\n  frameworkInstanceId String?\n  status              AuditStatus @default(planned)\n  auditorName         String?\n  auditorOrganization String?\n  scheduledStartDate  DateTime?\n  scheduledEndDate    DateTime?\n  actualStartDate     DateTime?\n  actualEndDate       DateTime?\n  createdAt           DateTime    @default(now())\n  updatedAt           DateTime    @updatedAt\n\n  tenant            Tenant             @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  frameworkInstance FrameworkInstance? @relation(fields: [frameworkInstanceId], references: [id])\n  findings          AuditFinding[]\n  documents         AuditDocument[]\n\n  @@index([tenantId])\n}\n\nmodel AuditFinding {\n  id           String               @id @default(cuid())\n  auditId      String\n  tenantId     String\n  title        String\n  description  String?\n  severity     AuditFindingSeverity\n  status       AuditFindingStatus   @default(open)\n  controlId    String?\n  assignedToId String?\n  dueDate      DateTime?\n  resolvedAt   DateTime?\n  createdAt    DateTime             @default(now())\n  updatedAt    DateTime             @updatedAt\n\n  audit      Audit    @relation(fields: [auditId], references: [id], onDelete: Cascade)\n  tenant     Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  control    Control? @relation(fields: [controlId], references: [id])\n  assignedTo User?    @relation(\"AuditFindingAssignee\", fields: [assignedToId], references: [id])\n\n  @@index([tenantId])\n  @@index([auditId])\n}\n\nmodel AuditDocument {\n  id           String   @id @default(cuid())\n  auditId      String\n  tenantId     String\n  fileName     String?\n  fileKey      String\n  fileSize     Int?\n  mimeType     String?\n  uploadedById String\n  createdAt    DateTime @default(now())\n\n  audit      Audit  @relation(fields: [auditId], references: [id], onDelete: Cascade)\n  tenant     Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  uploadedBy User   @relation(\"AuditDocumentUploader\", fields: [uploadedById], references: [id])\n\n  @@index([tenantId])\n  @@index([auditId])\n}\n\n// --- bcp.prisma ---\nenum BCPStatus {\n  draft\n  approved\n  active\n  under_review\n  archived\n}\n\nenum CriticalityLevel {\n  mission_critical\n  business_critical\n  business_operational\n  administrative\n}\n\nenum BCPExerciseType {\n  tabletop\n  walkthrough\n  simulation\n  full_scale\n}\n\nenum BCPExerciseStatus {\n  planned\n  scheduled\n  in_progress\n  conducted\n  reviewed\n  cancelled\n}\n\nenum BCPExerciseOutcome {\n  not_met\n  partially_met\n  met\n  exceeded\n}\n\nenum BIAStatus {\n  draft\n  under_review\n  approved\n  archived\n}\n\nmodel BusinessContinuityPlan {\n  id             String    @id @default(cuid())\n  tenantId       String\n  title          String\n  description    String?\n  version        String?\n  status         BCPStatus @default(draft)\n  ownerId        String\n  approvedAt     DateTime?\n  lastReviewedAt DateTime?\n  nextReviewDate DateTime?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  tenant         Tenant                   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  owner          User                     @relation(\"BCPOwner\", fields: [ownerId], references: [id])\n  impactAnalyses BusinessImpactAnalysis[]\n  exercises      BCPExercise[]\n\n  @@index([tenantId])\n}\n\nmodel BusinessImpactAnalysis {\n  id                        String           @id @default(cuid())\n  tenantId                  String\n  bcpId                     String\n  processName               String\n  description               String?\n  criticalityLevel          CriticalityLevel\n  rtoHours                  Int\n  rpoHours                  Int\n  maxTolerableDowntimeHours Int\n  // MTPD (Maximum Tolerable Period of Disruption) is the regulatory ceiling for\n  // how long the process can be unavailable before unacceptable harm occurs.\n  // RTO must be <= MTPD; the UI surfaces violations as a gap.\n  mtpdHours                 Int?\n  financialImpactPerHour    Decimal?\n  dependencies              String?\n\n  // Qualitative impact narratives — covered by ISO 22301 §8.2.2 alongside\n  // financial impact. Free-text so each org can describe in their own terms.\n  operationalImpact  String?\n  regulatoryImpact   String?\n  reputationalImpact String?\n\n  // Lifecycle / governance — ISO 22301 requires BIAs to be approved, owned,\n  // and periodically reviewed.\n  status         BIAStatus @default(draft)\n  ownerId        String?\n  approvedAt     DateTime?\n  lastReviewedAt DateTime?\n  nextReviewDate DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tenant Tenant                 @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  bcp    BusinessContinuityPlan @relation(fields: [bcpId], references: [id], onDelete: Cascade)\n  owner  User?                  @relation(\"BIAOwner\", fields: [ownerId], references: [id])\n\n  @@index([tenantId])\n  @@index([bcpId])\n  @@index([status])\n  @@index([criticalityLevel])\n  @@index([nextReviewDate])\n}\n\nmodel BCPExercise {\n  id            String            @id @default(cuid())\n  tenantId      String\n  bcpId         String\n  title         String\n  type          BCPExerciseType\n  scheduledDate DateTime?\n  conductedDate DateTime?\n  status        BCPExerciseStatus @default(planned)\n\n  // ── Pre-exercise design (ISO 22301 §8.5 — exercise programme) ──\n  // Free-text by design: a structured scenario library is a clean follow-up\n  // and would otherwise force migrations on every template change.\n  scenario      String?\n  objectives    String?\n  // Which plans/processes/locations/systems were in scope.\n  scope         String?\n  facilitatorId String?\n  // Comma- or newline-separated names. Promote to a join table once the\n  // user base needs RACI assignment per participant.\n  participants  String?\n\n  // ── Outcome / after-action review ──\n  outcomeRating  BCPExerciseOutcome?\n  // Actual recovery achieved during the exercise — closes the loop back to\n  // the BIA targets so the team can spot when stated RTO/RPO is unrealistic.\n  actualRtoHours Int?\n  actualRpoHours Int?\n  findings       String?\n  lessonsLearned String?\n  // One action per line (free-text). Future work: link to Tasks for tracking.\n  actionItems    String?\n\n  // ── Cadence ──\n  nextExerciseDate DateTime?\n  reviewedAt       DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tenant      Tenant                 @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  bcp         BusinessContinuityPlan @relation(fields: [bcpId], references: [id], onDelete: Cascade)\n  facilitator User?                  @relation(\"BCPExerciseFacilitator\", fields: [facilitatorId], references: [id])\n\n  @@index([tenantId])\n  @@index([bcpId])\n  @@index([status])\n  @@index([scheduledDate])\n  @@index([conductedDate])\n}\n\n// --- billing.ee.prisma ---\n// EE: Trustalo-managed LiteLLM routing + metered billing.\n//\n// This schema is loaded when running prisma:combine. It models the\n// minimum state needed to:\n//   - provision and refresh per-tenant LiteLLM virtual keys\n//   - track prepaid credit balance (1 credit == 1 USD; markup is\n//     baked into the purchase price)\n//   - record per-call spend events for audit + reconciliation\n//   - roll those events up monthly for fast dashboard reads\n//\n// All tables are gated at the application layer behind the `ai-metered`\n// feature id (see packages/license/src/types.ts). Self-hosted\n// deployments without an EE license will simply never write to them.\n\nenum TenantBillingMode {\n  // Trustalo pays the upstream provider via its master account on\n  // LiteLLM. Tenant pays Trustalo at the markup-inclusive credit price.\n  managed\n  // Tenant brings their own provider keys. LiteLLM proxies their\n  // traffic for logging/governance only; Trustalo applies 0% markup\n  // on inference and bills only the platform fee.\n  byok_passthrough\n  // Operator has explicitly disabled metering for this tenant\n  // (e.g. internal accounts, partner accounts). Skips wallet checks\n  // and never debits. Should be used sparingly.\n  disabled\n}\n\nenum TenantLiteLLMKeyStatus {\n  active\n  suspended\n  expired\n  rotating\n}\n\nmodel TenantBillingConfig {\n  id                        String            @id @default(cuid())\n  tenantId                  String            @unique\n  mode                      TenantBillingMode @default(managed)\n  // Hard ceiling (in microcents) the tenant can ever spend per month\n  // regardless of wallet balance. Defence-in-depth against runaway\n  // costs from a compromised account. `null` means unlimited.\n  monthlySpendCapMicrocents BigInt?\n  // Operator overrides for tier mapping. When set, takes precedence\n  // over the per-feature `AIFeatureConfig.model`. Used for partner /\n  // dev accounts that need a non-default routing.\n  modelTierOverride         String?\n  createdAt                 DateTime          @default(now())\n  updatedAt                 DateTime          @updatedAt\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId])\n}\n\nmodel TenantLiteLLMKey {\n  id                      String                 @id @default(cuid())\n  tenantId                String                 @unique\n  // LiteLLM's identifier for the key (its `/key/info` \"token\" hash).\n  // Stable across rotations — only `virtualKeyCipher` changes.\n  litellmKeyId            String                 @unique\n  // AES-256-GCM ciphertext of the actual virtual key. NEVER logged\n  // and decrypted lazily inside the resolver hot path.\n  virtualKeyCipher        String\n  // Comma-separated model aliases this key may use. Enforced\n  // server-side by LiteLLM; mirrored here for fast pre-flight checks.\n  modelAllowlist          String[]\n  status                  TenantLiteLLMKeyStatus @default(active)\n  // Max budget configured on LiteLLM for this key, in microcents.\n  // `null` means no cap (managed-mode wallets enforce the cap via\n  // top-up balance; pass-through mode usually leaves this null).\n  budgetMaxMicrocents     BigInt?\n  // Last-known LiteLLM-reported spend for reconciliation. Source of\n  // truth lives on LiteLLM; this is a cache to detect drift.\n  observedSpendMicrocents BigInt                 @default(0)\n  lastSyncedAt            DateTime?\n  createdAt               DateTime               @default(now())\n  updatedAt               DateTime               @updatedAt\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId])\n}\n\nmodel CreditWallet {\n  id                            String   @id @default(cuid())\n  tenantId                      String   @unique\n  // Available credits in microcents (USD). 1 credit == 1 USD ==\n  // 1_000_000 microcents. Cannot go negative — the LLM path checks\n  // this before resolving and 402s when zero.\n  balanceMicrocents             BigInt   @default(0)\n  // Lifetime stats for the dashboard.\n  lifetimeCreditedMicrocents    BigInt   @default(0)\n  lifetimeDebitedMicrocents     BigInt   @default(0)\n  // Low-balance warning threshold (in microcents). When the balance\n  // crosses this downward, a TaskService notification fires. `null`\n  // means use the operator-level default.\n  lowBalanceThresholdMicrocents BigInt?\n  createdAt                     DateTime @default(now())\n  updatedAt                     DateTime @updatedAt\n\n  tenant       Tenant              @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  transactions CreditTransaction[]\n\n  @@index([tenantId])\n}\n\nenum CreditTransactionKind {\n  // Tenant purchased credits via Stripe.\n  purchase\n  // Operator gifted credits (trial, support credit, etc.).\n  grant\n  // Refund of a prior purchase (Stripe webhook).\n  refund\n  // LLM call debited the wallet (signed negative).\n  debit\n  // Reconciliation correction after spend-sync detected drift.\n  adjustment\n  // Promotional credit that expires.\n  promotion_expiry\n}\n\nmodel CreditTransaction {\n  id                     String                @id @default(cuid())\n  walletId               String\n  tenantId               String\n  // Signed amount. Positive for credits added, negative for debits.\n  amountMicrocents       BigInt\n  kind                   CreditTransactionKind\n  // Free-form human-readable reason. Surfaced in the billing UI.\n  reason                 String?\n  // For purchase/refund: the Stripe checkout session / payment intent.\n  // For debit: the LiteLLMSpendEvent.id that triggered the debit.\n  // For adjustment: the reconciliation run id.\n  externalRef            String?\n  // Snapshot of wallet balance AFTER applying this transaction. Lets\n  // the UI render a running balance without re-summing the entire log.\n  balanceAfterMicrocents BigInt\n  createdAt              DateTime              @default(now())\n\n  wallet CreditWallet @relation(fields: [walletId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId, createdAt])\n  @@index([walletId, createdAt])\n}\n\nmodel LiteLLMSpendEvent {\n  id                 String    @id @default(cuid())\n  tenantId           String\n  feature            AIFeature\n  model              String\n  promptTokens       Int\n  completionTokens   Int\n  // Raw upstream cost reported by LiteLLM, in microcents (×1_000_000).\n  // Stored at microcent precision because individual completions can\n  // cost less than a full cent.\n  rawCostMicrocents  BigInt\n  // After Trustalo's markup. For BYOK pass-through this equals raw.\n  markedUpMicrocents BigInt\n  // LiteLLM's request id. Indexed unique so the spend sync is\n  // idempotent and a webhook retry never double-debits.\n  litellmRequestId   String    @unique\n  occurredAt         DateTime\n  createdAt          DateTime  @default(now())\n\n  @@index([tenantId, occurredAt])\n  @@index([tenantId, feature, occurredAt])\n}\n\nmodel TenantAIUsageMonth {\n  tenantId               String\n  // ISO month, e.g. \"2026-05\". Cheaper than a DateTime when the only\n  // operation is monthly grouping.\n  yearMonth              String\n  totalPromptTokens      Int      @default(0)\n  totalCompletionTokens  Int      @default(0)\n  // Aggregate raw cost (microcents) — useful for cost-of-goods reports.\n  totalRawCostMicrocents BigInt   @default(0)\n  // Aggregate billed cost (microcents) — what hit the wallet.\n  totalBilledMicrocents  BigInt   @default(0)\n  // JSON breakdown by feature/model: { \"chat_assistant\": { tokens, billed }, ... }\n  byFeature              Json     @default(\"{}\")\n  updatedAt              DateTime @updatedAt\n\n  @@id([tenantId, yearMonth])\n}\n\n// --- chat.prisma ---\n// ============================================================\n// Chat — general compliance assistant.\n//\n// Phase 2 of the \"ongoing AI context\" plan. A `Conversation` is a\n// chat thread between a user and the assistant. Each `Message` is\n// one turn (user prompt or assistant reply).\n//\n// Design notes\n// ────────────\n// • The assistant is grounded against TenantContext + the\n//   tenant's policies/risks/vendors/controls/frameworks. Each reply\n//   stores `groundingHash` so audit reviewers can prove the assistant\n//   was given exactly the same evidence on a re-run.\n// • In parallel with the reply, an extraction worker scans the user's\n//   turn for new facts and writes TenantContextProposal rows.\n//   The ids of any proposals tied to a given assistant turn live in\n//   `Message.proposalIds` so the UI can deep-link.\n// • No tool-calling — the assistant cannot mutate tenant data. All\n//   \"context updates\" go through the proposal review surface.\n// • Conversations are tenant-scoped; the prismaWithTenant extension\n//   injects `tenantId` automatically.\n// ============================================================\n\nenum MessageRole {\n  user\n  assistant\n  system\n}\n\nmodel Conversation {\n  id         String    @id @default(cuid())\n  tenantId   String\n  /// Auto-derived from the first user turn when null. Editable by the\n  /// user from the conversation list.\n  title      String?\n  createdBy  String\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n  /// Soft-archive — hides from the list without deleting transcript.\n  archivedAt DateTime?\n\n  tenant   Tenant    @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  messages Message[]\n\n  @@index([tenantId])\n  @@index([tenantId, archivedAt, updatedAt])\n  @@index([createdBy])\n}\n\nmodel Message {\n  id             String      @id @default(cuid())\n  tenantId       String\n  conversationId String\n  role           MessageRole\n  content        String      @db.Text\n  /// Provider/model used to produce this assistant message — null for\n  /// user/system messages. Surfaced in the UI footer for transparency.\n  modelUsed      String?\n  /// Source of the resolved provider (operator default / org provider /\n  /// per-feature override). Mirrors the AdvisoryBanner pattern.\n  providerSource String?\n  /// Deterministic hash of the grounding bundle (context ids + policy\n  /// ids + risk ids + vendor ids + recent message ids + truncation\n  /// caps). Same hash means same evidence → reproducible answers in\n  /// audits.\n  groundingHash  String?\n  /// Structured citations: array of { kind, id, label } objects the\n  /// model emitted to back claims in `content`. Validated against the\n  /// grounding bundle before persistence — citations to ids that\n  /// weren't in the bundle are dropped to prevent hallucinated\n  /// references.\n  citations      Json        @default(\"[]\")\n  /// TenantContextProposal ids that the parallel extractor\n  /// produced from the *user* turn paired with this assistant turn.\n  /// Used by the right-side proposal panel to highlight which turn a\n  /// given proposal came from.\n  proposalIds    String[]    @default([])\n  createdAt      DateTime    @default(now())\n\n  tenant       Tenant       @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  conversation Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId])\n  @@index([conversationId, createdAt])\n}\n\n// --- control.prisma ---\nenum ControlStatus {\n  not_implemented\n  partially_implemented\n  implemented\n  not_applicable\n}\n\nmodel Control {\n  id                    String        @id @default(cuid())\n  tenantId              String\n  title                 String\n  description           String?\n  implementationDetails String?       @db.Text\n  status                ControlStatus @default(not_implemented)\n  category              String?\n  ownerId               String?\n  reviewDate            DateTime?\n  lastReviewedAt        DateTime?\n  createdAt             DateTime      @default(now())\n  updatedAt             DateTime      @updatedAt\n\n  tenant                        Tenant                           @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  owner                         User?                            @relation(\"ControlOwner\", fields: [ownerId], references: [id])\n  controlRequirementAssignments ControlRequirementAssignment[]\n  auditFindings                 AuditFinding[]\n  tasks                         Task[]\n  evidence                      Evidence[]\n  policyControls                PolicyControl[]\n  evidenceCollectionConfig      ControlEvidenceCollectionConfig?\n  weaknesses                    ControlWeakness[]\n\n  @@index([tenantId])\n}\n\n// ── Evidence collection mode (per-control, per-tenant) ────────\n//\n// Lets a user choose whether evidence for a control is gathered\n// manually (existing behaviour) or by the Evidence Agent. In agent\n// mode, `agentInstructions` is the natural-language directive the\n// LLM receives, and `agentToolConnectionIds` are the collector\n// IntegrationConnection IDs the agent is allowed to call as tools.\nenum EvidenceCollectionMode {\n  manual\n  agent\n}\n\nenum EvidenceAgentLastStatus {\n  idle\n  queued\n  running\n  succeeded\n  failed\n}\n\nmodel ControlEvidenceCollectionConfig {\n  id                     String                  @id @default(cuid())\n  tenantId               String\n  controlId              String                  @unique\n  mode                   EvidenceCollectionMode  @default(manual)\n  agentInstructions      String?                 @db.Text\n  agentToolConnectionIds String[]                @default([])\n  agentScheduleMinutes   Int?\n  agentLastRunAt         DateTime?\n  agentLastStatus        EvidenceAgentLastStatus @default(idle)\n  agentLastRunId         String?\n  agentLastSummary       String?                 @db.Text\n  createdAt              DateTime                @default(now())\n  updatedAt              DateTime                @updatedAt\n\n  control Control @relation(fields: [controlId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId])\n  @@index([tenantId, mode])\n}\n\n// ── ControlWeakness ─────────────────────────────────────────────────\n//\n// Tracks information-security control weaknesses for the APRA CPS 234\n// Para 35 10-business-day notification clock. The model is generic\n// enough to also support other regulator weakness-notification clocks\n// later (e.g. CPS 230 operational risk) — the CPS 234 specifics live\n// in the helper `computeCps234ControlWeaknessDeadline` and the router.\n//\n// Lifecycle (mirrors `DataBreachStatus`):\n//   open       — discovered, not yet triaged\n//   triaging   — materiality + remediability under assessment\n//   notified   — APRA has been notified (or a nil-return recorded)\n//   remediating — material; remediation in flight\n//   closed     — no longer material OR remediation complete\n//\n// `notificationDeadlineAt` is a snapshot of the 10-BD clock taken at\n// `discoveredAt`. The router recomputes it when `discoveredAt` changes\n// unless the caller explicitly overrides it (mirrors `DataBreach`).\nenum ControlWeaknessSeverity {\n  low\n  medium\n  high\n  critical\n}\n\nenum ControlWeaknessStatus {\n  open\n  triaging\n  notified\n  remediating\n  closed\n}\n\nenum ControlWeaknessRemediabilityDecision {\n  pending\n  remediable_in_time\n  not_remediable_in_time\n}\n\nmodel ControlWeakness {\n  id        String  @id @default(cuid())\n  tenantId  String\n  /// Optional link to the control whose weakness this records. Nullable\n  /// because a weakness may surface before the control is catalogued\n  /// (e.g. from a pen-test finding or third-party attestation gap).\n  controlId String?\n\n  title       String\n  description String?                 @db.Text\n  severity    ControlWeaknessSeverity\n  status      ControlWeaknessStatus   @default(open)\n\n  // Timeline.\n  discoveredAt           DateTime  @default(now())\n  /// Snapshot of `discoveredAt + 10 business days` at create-time per\n  /// CPS 234 Para 35. Stored explicitly so reviewers can override the\n  /// computed value when the discovery point itself is uncertain.\n  notificationDeadlineAt DateTime\n  /// Date by which the entity expects to remediate. Used by the\n  /// router/UI to surface \"remediation will overrun the 10-BD clock\".\n  expectedRemediationAt  DateTime?\n  remediatedAt           DateTime?\n\n  /// Materiality + remediability decision (Para 35 trigger).\n  /// `pending`              — entity still assessing.\n  /// `remediable_in_time`   — material, but expected to be remediated\n  ///                          within an entity-defined timely window\n  ///                          (no notification required).\n  /// `not_remediable_in_time` — APRA notification required within 10\n  ///                          business days of becoming aware.\n  remediability ControlWeaknessRemediabilityDecision @default(pending)\n\n  rootCause       String? @db.Text\n  remediationPlan String? @db.Text\n\n  /// APRA notification (Para 35).\n  apraNotificationRequired Boolean   @default(false)\n  apraNotifiedAt           DateTime?\n  apraReference            String?\n\n  reportedById String?\n  assigneeId   String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tenant     Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  control    Control? @relation(fields: [controlId], references: [id], onDelete: SetNull)\n  reportedBy User?    @relation(\"ControlWeaknessReporter\", fields: [reportedById], references: [id])\n  assignee   User?    @relation(\"ControlWeaknessAssignee\", fields: [assigneeId], references: [id])\n\n  @@index([tenantId])\n  @@index([status])\n  @@index([severity])\n  @@index([notificationDeadlineAt])\n  @@index([discoveredAt])\n}\n\n// --- evidence.prisma ---\nenum EvidenceType {\n  document\n  screenshot\n  link\n  automated\n  attestation\n}\n\nenum EvidenceApprovalStatus {\n  draft\n  pending_review\n  approved\n  rejected\n  expired\n  stale\n}\n\nenum RenewalFrequency {\n  once\n  monthly\n  quarterly\n  semi_annually\n  annually\n}\n\nmodel Evidence {\n  id          String                 @id @default(cuid())\n  tenantId    String\n  controlId   String\n  title       String\n  description String?\n  type        EvidenceType           @default(document)\n  status      EvidenceApprovalStatus @default(draft)\n\n  fileKey  String?\n  fileName String?\n  fileSize Int?\n  mimeType String?\n\n  externalUrl String?\n\n  sourceType String?\n  sourceId   String?\n\n  collectedAt DateTime  @default(now())\n  validFrom   DateTime  @default(now())\n  expiresAt   DateTime?\n\n  renewalFrequency   RenewalFrequency?\n  nextRenewalDate    DateTime?\n  reminderDaysBefore Int               @default(30)\n  lastReminderSentAt DateTime?\n\n  // Nullable to support automated submitters such as the per-control\n  // Evidence Agent, which has no associated user identity. Manual\n  // submissions from the UI continue to populate this with the\n  // signed-in user's id.\n  submittedById String?\n  reviewedById  String?\n  reviewedAt    DateTime?\n  reviewNotes   String?\n\n  tags     String[]\n  metadata Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tenant      Tenant  @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  control     Control @relation(fields: [controlId], references: [id], onDelete: Cascade)\n  submittedBy User?   @relation(\"EvidenceSubmittedBy\", fields: [submittedById], references: [id])\n  reviewedBy  User?   @relation(\"EvidenceReviewedBy\", fields: [reviewedById], references: [id])\n\n  @@index([tenantId])\n  @@index([controlId])\n  @@index([expiresAt])\n  @@index([status])\n}\n\n// --- framework.prisma ---\nenum FrameworkType {\n  iso27001\n  iso27017\n  iso27018\n  iso22301\n  iso42001\n  soc2\n  essential8\n  nist_csf_2\n  gdpr\n  cps234\n}\n\nenum FrameworkInstanceStatus {\n  not_started\n  in_progress\n  ready_for_audit\n  certified\n}\n\nenum MappingRelationship {\n  equivalent // 1:1 same control intent\n  partial // overlapping but not identical\n  informs // referenced as supporting guidance\n}\n\nmodel Framework {\n  id            String        @id @default(cuid())\n  name          String\n  version       String\n  description   String?\n  frameworkType FrameworkType\n  totalControls Int\n  isActive      Boolean       @default(true)\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  instances    FrameworkInstance[]\n  requirements Requirement[]\n}\n\nmodel FrameworkInstance {\n  id                  String                  @id @default(cuid())\n  tenantId            String\n  frameworkId         String\n  status              FrameworkInstanceStatus @default(not_started)\n  isEnabled           Boolean                 @default(true)\n  targetDate          DateTime?\n  certifiedAt         DateTime?\n  // Optional target maturity/tier for tiered frameworks\n  // (e.g. Essential Eight: \"ml1\"/\"ml2\"/\"ml3\"; NIST CSF: \"tier1\"–\"tier4\").\n  // Null for non-tiered frameworks.\n  targetMaturityLevel String?\n  createdAt           DateTime                @default(now())\n  updatedAt           DateTime                @updatedAt\n\n  tenant                        Tenant                         @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  framework                     Framework                      @relation(fields: [frameworkId], references: [id])\n  controlRequirementAssignments ControlRequirementAssignment[]\n  audits                        Audit[]\n\n  @@unique([tenantId, frameworkId])\n  @@index([tenantId])\n}\n\nmodel Requirement {\n  id               String  @id @default(cuid())\n  frameworkId      String\n  identifier       String\n  title            String\n  description      String?\n  evidenceGuidance String?\n  category         String?\n  // Optional maturity/tier marker for tiered frameworks\n  // (e.g. Essential Eight: \"ml1\"/\"ml2\"/\"ml3\"; NIST CSF tiers if used per-requirement).\n  // Allows the UI to dim/highlight requirements based on the org's targetMaturityLevel.\n  maturityLevel    String?\n  sortOrder        Int\n\n  framework                     Framework                      @relation(fields: [frameworkId], references: [id], onDelete: Cascade)\n  controlRequirementAssignments ControlRequirementAssignment[]\n  mappingsAsSource              FrameworkRequirementMapping[]  @relation(\"MappingSource\")\n  mappingsAsTarget              FrameworkRequirementMapping[]  @relation(\"MappingTarget\")\n\n  @@index([frameworkId])\n}\n\n// Catalog-level cross-framework requirement mapping (org-agnostic).\n// Pre-seeded from authoritative sources (NIST CSF Informative References,\n// ACSC Essential Eight mapping appendix, AICPA SOC 2 mappings, etc.) so\n// evidence collected for one framework can satisfy mapped requirements\n// in others. Distinct from ControlRequirementAssignment which is org-scoped.\nmodel FrameworkRequirementMapping {\n  id                  String              @id @default(cuid())\n  sourceRequirementId String\n  targetRequirementId String\n  relationship        MappingRelationship @default(partial)\n  rationale           String?\n  source              String // e.g. \"NIST CSF 2.0 Informative References v1.0\"\n  createdAt           DateTime            @default(now())\n\n  sourceRequirement Requirement @relation(\"MappingSource\", fields: [sourceRequirementId], references: [id], onDelete: Cascade)\n  targetRequirement Requirement @relation(\"MappingTarget\", fields: [targetRequirementId], references: [id], onDelete: Cascade)\n\n  @@unique([sourceRequirementId, targetRequirementId, relationship])\n  @@index([sourceRequirementId])\n  @@index([targetRequirementId])\n}\n\nmodel ControlRequirementAssignment {\n  id                  String  @id @default(cuid())\n  tenantId            String\n  requirementId       String\n  controlId           String\n  frameworkInstanceId String\n  status              String?\n\n  tenant            Tenant            @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  requirement       Requirement       @relation(fields: [requirementId], references: [id])\n  control           Control           @relation(fields: [controlId], references: [id])\n  frameworkInstance FrameworkInstance @relation(fields: [frameworkInstanceId], references: [id])\n\n  @@unique([controlId, frameworkInstanceId, requirementId])\n  @@index([tenantId])\n}\n\n// --- incident.prisma ---\nenum IncidentSeverity {\n  critical\n  high\n  medium\n  low\n  informational\n}\n\nenum IncidentStatus {\n  reported\n  investigating\n  contained\n  resolved\n  closed\n  lessons_learned\n}\n\nmodel Incident {\n  id                             String           @id @default(cuid())\n  tenantId                       String\n  title                          String\n  description                    String?\n  severity                       IncidentSeverity\n  status                         IncidentStatus   @default(reported)\n  reportedById                   String\n  assignedToId                   String?\n  detectedAt                     DateTime?\n  resolvedAt                     DateTime?\n  rootCause                      String?\n  regulatoryNotificationRequired Boolean          @default(false)\n  regulatoryNotifiedAt           DateTime?\n  createdAt                      DateTime         @default(now())\n  updatedAt                      DateTime         @updatedAt\n\n  tenant     Tenant             @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  reportedBy User               @relation(\"IncidentReporter\", fields: [reportedById], references: [id])\n  assignedTo User?              @relation(\"IncidentAssignee\", fields: [assignedToId], references: [id])\n  timeline   IncidentTimeline[]\n\n  @@index([tenantId])\n}\n\nmodel IncidentTimeline {\n  id            String   @id @default(cuid())\n  incidentId    String\n  tenantId      String\n  action        String\n  description   String?\n  performedById String\n  createdAt     DateTime @default(now())\n\n  incident    Incident @relation(fields: [incidentId], references: [id], onDelete: Cascade)\n  tenant      Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  performedBy User     @relation(fields: [performedById], references: [id])\n\n  @@index([tenantId])\n  @@index([incidentId])\n}\n\n// --- policy.prisma ---\nenum PolicyStatus {\n  draft\n  pending_approval\n  approved\n  published\n  archived\n}\n\nmodel Policy {\n  id               String       @id @default(cuid())\n  tenantId         String\n  title            String\n  description      String?\n  status           PolicyStatus @default(draft)\n  category         String?\n  ownerId          String\n  currentVersionId String?\n  renewalDate      DateTime?\n  // Phase 2 (AI accelerators): short Markdown summary surfaced on the\n  // public Trust Center for published policies. Generated once via the\n  // AI provider on first publish; admins can override manually.\n  publicSummary    String?      @db.Text\n  createdAt        DateTime     @default(now())\n  updatedAt        DateTime     @updatedAt\n\n  tenant          Tenant                 @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  owner           User                   @relation(\"PolicyOwner\", fields: [ownerId], references: [id])\n  versions        PolicyVersion[]\n  acknowledgments PolicyAcknowledgment[]\n  policyControls  PolicyControl[]\n  comments        PolicyComment[]\n\n  @@index([tenantId])\n}\n\nmodel PolicyVersion {\n  id            String    @id @default(cuid())\n  policyId      String\n  versionNumber Int\n  content       String    @db.Text\n  changeNotes   String?\n  createdById   String\n  approvedById  String?\n  approvedAt    DateTime?\n  createdAt     DateTime  @default(now())\n\n  policy          Policy                 @relation(fields: [policyId], references: [id], onDelete: Cascade)\n  createdBy       User                   @relation(\"PolicyVersionCreator\", fields: [createdById], references: [id])\n  approvedBy      User?                  @relation(\"PolicyVersionApprover\", fields: [approvedById], references: [id])\n  acknowledgments PolicyAcknowledgment[]\n  comments        PolicyComment[]\n\n  @@index([policyId])\n}\n\nmodel PolicyAcknowledgment {\n  id              String   @id @default(cuid())\n  policyId        String\n  policyVersionId String\n  userId          String\n  tenantId        String\n  acknowledgedAt  DateTime @default(now())\n  createdAt       DateTime @default(now())\n\n  policy        Policy        @relation(fields: [policyId], references: [id], onDelete: Cascade)\n  policyVersion PolicyVersion @relation(fields: [policyVersionId], references: [id])\n  user          User          @relation(fields: [userId], references: [id])\n  tenant        Tenant        @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId])\n  @@index([policyId])\n}\n\nmodel PolicyComment {\n  id              String    @id @default(cuid())\n  policyId        String\n  policyVersionId String?\n  userId          String\n  tenantId        String\n  content         String    @db.Text\n  highlightedText String?   @db.Text\n  fromPos         Int?\n  toPos           Int?\n  resolved        Boolean   @default(false)\n  resolvedById    String?\n  resolvedAt      DateTime?\n  parentId        String?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  policy        Policy          @relation(fields: [policyId], references: [id], onDelete: Cascade)\n  policyVersion PolicyVersion?  @relation(fields: [policyVersionId], references: [id])\n  user          User            @relation(\"PolicyCommentAuthor\", fields: [userId], references: [id])\n  tenant        Tenant          @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  resolvedBy    User?           @relation(\"PolicyCommentResolver\", fields: [resolvedById], references: [id])\n  parent        PolicyComment?  @relation(\"CommentReplies\", fields: [parentId], references: [id], onDelete: Cascade)\n  replies       PolicyComment[] @relation(\"CommentReplies\")\n\n  @@index([policyId])\n  @@index([policyVersionId])\n  @@index([tenantId])\n  @@index([parentId])\n}\n\nmodel PolicyControl {\n  id        String   @id @default(cuid())\n  policyId  String\n  controlId String\n  tenantId  String\n  createdAt DateTime @default(now())\n\n  policy  Policy  @relation(fields: [policyId], references: [id], onDelete: Cascade)\n  control Control @relation(fields: [controlId], references: [id], onDelete: Cascade)\n  tenant  Tenant  @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@unique([policyId, controlId])\n  @@index([tenantId])\n  @@index([policyId])\n  @@index([controlId])\n}\n\n/// System-wide policy library (not tenant-scoped). Seeded on install; extend FrameworkType in schema for new frameworks.\nmodel PolicyTemplate {\n  id               String          @id @default(cuid())\n  slug             String          @unique\n  title            String\n  shortDescription String?\n  /// Suggested category for the new policy record\n  category         String?\n  /// Empty array = applies to all current frameworks; otherwise filter by overlap\n  frameworkTypes   FrameworkType[]\n  /// Future-proof labels (e.g. \"hipaa\", \"pci\") without enum migration — informational / filter\n  tags             String[]        @default([])\n  contentHtml      String          @db.Text\n  sortOrder        Int             @default(0)\n  isActive         Boolean         @default(true)\n  createdAt        DateTime        @default(now())\n  updatedAt        DateTime        @updatedAt\n\n  @@index([isActive, sortOrder])\n}\n\n// --- privacy.prisma ---\n// ============================================================\n// GDPR / Privacy program models\n//\n// The privacy module is built around four registers, each parallel to a\n// concrete GDPR obligation:\n//\n//   1. ProcessingActivity  — Article 30 Records of Processing Activities (RoPA)\n//   2. DPIA                — Article 35 Data Protection Impact Assessments\n//   3. DataBreach          — Articles 33/34 Personal-data breach notifications\n//   4. DSARRequest         — Articles 12–22 Data-Subject Access Requests\n//\n// The shape mirrors the patterns established by AI Governance (similar\n// `*Status` lifecycle enums, approver fields, indexes) so the API and UI\n// layers can reuse the same conventions.\n// ============================================================\n\n// ── Lawful basis under Art. 6(1) ───────────────────────────────────────\nenum LawfulBasis {\n  consent\n  contract\n  legal_obligation\n  vital_interests\n  public_task\n  legitimate_interests\n}\n\n// ── Categories of personal data on a processing activity ───────────────\n// Distinct from \"sensitive\" — special_category and criminal trigger Art. 9/10.\nenum DataCategory {\n  identity\n  contact\n  financial\n  health\n  location\n  online_identifier\n  demographic\n  employment\n  usage\n  special_category\n  criminal\n  other\n}\n\n// ── Categories of data subject ─────────────────────────────────────────\nenum SubjectCategory {\n  customer\n  employee\n  prospect\n  supplier_contact\n  minor\n  website_visitor\n  patient\n  other\n}\n\n// ── Cross-border transfer safeguard (Chapter V) ────────────────────────\nenum TransferMechanism {\n  none_eu_eea\n  adequacy_decision\n  scc\n  bcr\n  derogation_art_49\n}\n\n// ── Role of the organisation in the processing activity ────────────────\nenum ProcessingRole {\n  controller\n  processor\n  joint_controller\n}\n\nenum ProcessingActivityStatus {\n  draft\n  active\n  under_review\n  retired\n}\n\n// ── DPIA lifecycle. Mirrors AIImpactStatus by intent so reviewers see a\n//    familiar approve/reject pattern across modules. ───────────────────\nenum DPIAStatus {\n  draft\n  in_review\n  approved\n  rejected\n}\n\n// ── Article 35(3) DPIA-necessity outcome ───────────────────────────────\nenum DPIANecessity {\n  required\n  recommended\n  not_required\n}\n\n// ── Personal-data breach taxonomy ──────────────────────────────────────\n// Severity mirrors AIIncidentSeverity so the dashboard treatment is the same.\nenum DataBreachSeverity {\n  low\n  medium\n  high\n  critical\n}\n\n// CIA-style taxonomy used in WP29 / EDPB guidance for breach categorisation.\nenum DataBreachCategory {\n  confidentiality\n  integrity\n  availability\n  combined\n}\n\nenum DataBreachStatus {\n  open\n  investigating\n  contained\n  notified\n  closed\n}\n\n// ── DSAR taxonomy ──────────────────────────────────────────────────────\nenum DSARType {\n  access\n  rectification\n  erasure\n  restriction\n  portability\n  objection\n  automated_decision\n  withdraw_consent\n}\n\nenum DSARStatus {\n  received\n  identity_pending\n  in_progress\n  extended\n  fulfilled\n  refused\n  closed\n}\n\nenum DSARChannel {\n  email\n  web_form\n  post\n  phone\n  in_person\n}\n\n// ─────────────────────────────────────────────────────────────────────────\n// Models\n// ─────────────────────────────────────────────────────────────────────────\n\n// Article 30 — Records of Processing Activities (RoPA)\n//\n// Each row describes one distinct purpose of personal-data processing carried\n// out by the organisation. This is THE defining GDPR artifact: every other\n// privacy resource (DPIA, breach scope, DSAR scope, sub-processor link) is\n// expressed in terms of one or more processing activities.\nmodel ProcessingActivity {\n  id       String @id @default(cuid())\n  tenantId String\n\n  // Human-readable name (e.g. \"Customer billing\", \"Employee performance reviews\").\n  name    String\n  // Specified, explicit, legitimate purpose under Art. 5(1)(b).\n  purpose String\n  // Whether the organisation acts as controller, processor or joint controller\n  // for THIS processing activity (an org can be controller in one and processor\n  // in another).\n  role    ProcessingRole @default(controller)\n\n  // Lawful basis under Art. 6(1) and the textual justification supporting it\n  // (e.g. for legitimate_interests the LIA outcome).\n  lawfulBasis              LawfulBasis\n  lawfulBasisJustification String?\n\n  // Inventory of what's processed and about whom.\n  dataCategories    DataCategory[]\n  subjectCategories SubjectCategory[]\n  // Free-form additional data-element list (\"first name, email, IP, etc.\").\n  dataElements      String[]\n  // Recipients to whom data is disclosed (categories or named entities).\n  recipients        String[]\n\n  // Cross-border transfers (Chapter V).\n  crossBorderTransfer  Boolean            @default(false)\n  transferMechanism    TransferMechanism?\n  transferDestinations String[]\n\n  // Retention & security narrative.\n  retentionPeriod  String?\n  securityMeasures String?\n\n  // Ownership.\n  ownerId String?\n  status  ProcessingActivityStatus @default(draft)\n\n  // Review cadence — used by the dashboard \"due for review\" KPI.\n  lastReviewedAt DateTime?\n  nextReviewAt   DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  owner  User?  @relation(\"ProcessingActivityOwner\", fields: [ownerId], references: [id])\n\n  dpias    DPIA[]\n  breaches DataBreach[]\n  dsars    DSARRequest[] @relation(\"DSARProcessingActivities\")\n  vendors  Vendor[]      @relation(\"VendorProcessingActivities\")\n  risks    Risk[]\n\n  @@index([tenantId])\n  @@index([status])\n  @@index([nextReviewAt])\n}\n\n// Article 35 — Data Protection Impact Assessment\n//\n// A DPIA is rooted to a single ProcessingActivity (the activity that triggered\n// the DPIA obligation). Multiple DPIAs are allowed per activity to support\n// re-assessment cycles.\nmodel DPIA {\n  id       String @id @default(cuid())\n  tenantId String\n\n  processingActivityId String\n  assessedById         String\n\n  title     String\n  // Article 35(3) DPIA-necessity outcome. `required` means the DPIA was\n  // mandatory; `recommended` means the org chose to do one for prudence.\n  necessity DPIANecessity @default(required)\n\n  // Narrative fields modelled on the EDPB DPIA template.\n  necessityProportionality String?\n  riskToRights             String?\n  mitigations              String?\n  consultedDpo             Boolean @default(false)\n  consultedDataSubjects    Boolean @default(false)\n\n  // Residual risk after mitigations — what triggers Art. 36 prior consultation.\n  residualRisk RiskRating?\n\n  status       DPIAStatus @default(draft)\n  approvedById String?\n  approvedAt   DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tenant             Tenant             @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  processingActivity ProcessingActivity @relation(fields: [processingActivityId], references: [id], onDelete: Cascade)\n  assessedBy         User               @relation(\"DPIAAssessor\", fields: [assessedById], references: [id])\n  approvedBy         User?              @relation(\"DPIAApprover\", fields: [approvedById], references: [id])\n\n  @@index([tenantId])\n  @@index([processingActivityId])\n  @@index([status])\n}\n\n// Articles 33/34 — Personal-data breach register\n//\n// `notificationDeadlineAt` is auto-computed as `discoveredAt + 72h` by the\n// API on create; the UI surfaces a countdown badge to the deadline. This\n// mirrors the AIIncident pattern with breach-specific fields layered on top.\nmodel DataBreach {\n  id       String @id @default(cuid())\n  tenantId String\n\n  // Optional link to the processing activity in scope. Null when the breach\n  // affects systems not yet captured in the RoPA.\n  processingActivityId String?\n\n  title       String\n  description String?\n  category    DataBreachCategory\n  severity    DataBreachSeverity\n  status      DataBreachStatus   @default(open)\n\n  // Timeline.\n  occurredAt             DateTime?\n  discoveredAt           DateTime  @default(now())\n  // Auto = discoveredAt + 72h. Stored explicitly so reviewers can override\n  // when discovery itself was uncertain (e.g. forensic investigation reveals\n  // an earlier discovery point).\n  notificationDeadlineAt DateTime\n  containedAt            DateTime?\n  resolvedAt             DateTime?\n\n  // Scope.\n  affectedRecordsEstimate   Int?\n  affectedSubjectCategories SubjectCategory[]\n  dataCategoriesInvolved    DataCategory[]\n\n  // Investigation.\n  rootCause   String?\n  containment String?\n  remediation String?\n\n  // Notification (Art. 33 + Art. 34).\n  supervisoryAuthorityNotificationRequired Boolean   @default(false)\n  supervisoryAuthorityNotifiedAt           DateTime?\n  supervisoryAuthorityReference            String?\n  dataSubjectsNotificationRequired         Boolean   @default(false)\n  dataSubjectsNotifiedAt                   DateTime?\n\n  reportedById String?\n  assigneeId   String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tenant             Tenant              @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  processingActivity ProcessingActivity? @relation(fields: [processingActivityId], references: [id])\n  reportedBy         User?               @relation(\"DataBreachReporter\", fields: [reportedById], references: [id])\n  assignee           User?               @relation(\"DataBreachAssignee\", fields: [assigneeId], references: [id])\n\n  @@index([tenantId])\n  @@index([status])\n  @@index([severity])\n  @@index([notificationDeadlineAt])\n  @@index([discoveredAt])\n}\n\n// Articles 12–22 — Data-Subject Access Requests (DSAR / DSR)\n//\n// `dueAt` is auto-computed as `receivedAt + 1 month`. `extendedDueAt` extends\n// by up to two further months under Art. 12(3). Both are surfaced as SLA\n// badges in the UI.\nmodel DSARRequest {\n  id       String @id @default(cuid())\n  tenantId String\n\n  // Identifies the data subject. We collect the minimum necessary; identity\n  // verification is captured separately (`identityVerifiedAt`).\n  subjectName       String\n  subjectEmail      String?\n  subjectIdentifier String?\n\n  requestType DSARType\n  channel     DSARChannel\n  status      DSARStatus  @default(received)\n\n  // Timeline & SLA.\n  receivedAt         DateTime  @default(now())\n  dueAt              DateTime\n  extendedAt         DateTime?\n  extendedDueAt      DateTime?\n  identityVerifiedAt DateTime?\n  fulfilledAt        DateTime?\n  closedAt           DateTime?\n\n  // Outcome.\n  refusalReason   String?\n  responseNotes   String?\n  // Optional storage key for any response artefact (export ZIP, etc.).\n  responseFileKey String?\n\n  // Free-form notes and an optional assignment.\n  assigneeId String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tenant               Tenant               @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  assignee             User?                @relation(\"DSARAssignee\", fields: [assigneeId], references: [id])\n  processingActivities ProcessingActivity[] @relation(\"DSARProcessingActivities\")\n\n  @@index([tenantId])\n  @@index([status])\n  @@index([requestType])\n  @@index([dueAt])\n}\n\n// --- questionnaires.prisma ---\n// ============================================================\n// Questionnaires — Phase 6 (AI accelerators).\n//\n// Customers regularly receive long security questionnaires (CAIQ,\n// SIG, Whistic, custom CSVs). The questionnaire workspace lets a\n// reviewer:\n//\n//   1. Import a questionnaire from CSV / CAIQ / SIG (we model this as\n//      a file-format hint plus the raw row data).\n//   2. Bulk-generate AI answers grounded in the org's existing policies,\n//      controls and TenantContext (the \"facts wallet\").\n//   3. Review, edit, approve and export the answered file in the\n//      original format so it can be returned to the requester.\n//\n// Each Answer carries provenance — generatedByAi flag, model used,\n// confidence, sources — so audit teams can prove which answers a human\n// reviewed vs accepted as-is.\n// ============================================================\n\nenum QuestionnaireSourceFormat {\n  csv\n  caiq\n  sig\n  xlsx\n  docx\n  custom\n}\n\nenum QuestionnaireStatus {\n  draft\n  in_progress\n  completed\n  exported\n}\n\nenum QuestionType {\n  yes_no\n  short_text\n  long_text\n  multiple_choice\n}\n\nenum AnswerStatus {\n  pending\n  draft\n  approved\n  rejected\n}\n\n/// Lifecycle of an asynchronous questionnaire import job.\n///\n///   pending   — row created, file uploaded to S3, runner not started yet\n///   running   — runner is parsing and/or calling the structure agent\n///   completed — all sheets understood; Questionnaire row + Questions persisted\n///   partial   — one or more sheets failed (agent timeout, schema rejection)\n///               but at least one question_table sheet succeeded; the user can\n///               accept the partial import or retry from the UI\n///   failed    — terminal failure (no usable sheets, AI unavailable, etc.)\nenum QuestionnaireImportJobStatus {\n  pending\n  running\n  completed\n  partial\n  failed\n}\n\n/// Async import job — owns the long-running work that POST /questionnaires\n/// used to do synchronously.\n///\n/// Why it exists:\n///   • Structure-agent calls on a 5-sheet workbook take 30–180 s. Holding an\n///     HTTP request open that long causes proxy timeouts (ALB 60 s default),\n///     duplicate submissions on browser retry, and a horrible \"stare at a\n///     spinner\" UX with no visibility into what's happening.\n///   • Per-sheet progress is what users actually want to see — a list of\n///     sheet names with ticks / spinners / failure markers is dramatically\n///     better than a three-minute opaque spinner.\n///\n/// Lifecycle:\n///   1. POST /questionnaires uploads the file to S3, creates this row with\n///      status=pending, kicks off the runner, and returns 202 + jobId.\n///   2. Runner sets status=running, parses sheets, and for each sheet calls\n///      the LLM mapper in parallel (`Promise.allSettled`). Each settle\n///      updates `progress.sheets[i]` so the UI poll can render per-sheet\n///      ticks/spinners.\n///   3. On success: creates the Questionnaire + Question rows, sets\n///      `questionnaireId` on this job, status=completed (or =partial if some\n///      sheets failed but at least one succeeded).\n///   4. On terminal failure: status=failed, errorMessage carries the public-\n///      safe copy.\n///\n/// We keep finished jobs in the table for audit/debug. A periodic janitor can\n/// purge rows older than N days; not in scope for the first cut.\nmodel QuestionnaireImportJob {\n  id               String                       @id @default(cuid())\n  tenantId         String\n  /// Final questionnaire name (carried so the UI can show the title even\n  /// while the job is still running).\n  name             String\n  requester        String?\n  vendorId         String?\n  dueDate          DateTime?\n  /// User-supplied format hint (csv | xlsx | docx | …). Optional; the runner\n  /// re-detects from file extension.\n  formatHint       QuestionnaireSourceFormat?\n  /// Detected source format once the runner has looked at the file.\n  sourceFormat     QuestionnaireSourceFormat?\n  /// S3 key of the uploaded original. Always set for xlsx/docx; null for\n  /// CSV-string imports (the CSV body is captured in `csvBody` instead).\n  originalFileKey  String?\n  originalFilename String?\n  originalMimeType String?\n  /// Verbatim CSV body for paste-CSV imports. We persist it on the job so\n  /// the runner can re-parse without round-tripping through S3.\n  csvBody          String?                      @db.Text\n  status           QuestionnaireImportJobStatus @default(pending)\n  /// Free-shape progress descriptor consumed by the polling UI:\n  ///   {\n  ///     phase: \"uploading\" | \"parsing\" | \"mapping\" | \"persisting\",\n  ///     totalSheets: number,\n  ///     completedSheets: number,\n  ///     sheets: [\n  ///       { name: string, status: \"pending\"|\"running\"|\"completed\"|\"failed\",\n  ///         kind?: \"instructions\"|\"metadata\"|\"question_table\"|\"matrix\",\n  ///         questionCount?: number, error?: string }\n  ///     ]\n  ///   }\n  /// Updated incrementally by the runner. The UI re-renders on every poll.\n  progress         Json                         @default(\"{}\")\n  /// Public-safe error message for status=failed/partial. NEVER contains\n  /// upstream secrets — the central error scrubber + AIProviderError public\n  /// messages enforce that.\n  errorMessage     String?                      @db.Text\n  errorCode        String?\n  /// Set when status transitions to completed/partial — points at the new\n  /// Questionnaire row so the UI can navigate to it.\n  questionnaireId  String?\n  createdById      String\n  createdAt        DateTime                     @default(now())\n  updatedAt        DateTime                     @updatedAt\n  startedAt        DateTime?\n  completedAt      DateTime?\n\n  tenant        Tenant         @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  createdBy     User           @relation(\"QuestionnaireImportJobCreator\", fields: [createdById], references: [id])\n  questionnaire Questionnaire? @relation(fields: [questionnaireId], references: [id], onDelete: SetNull)\n\n  @@index([tenantId])\n  @@index([tenantId, status])\n  @@index([tenantId, createdAt])\n}\n\nmodel Questionnaire {\n  id               String                    @id @default(cuid())\n  tenantId         String\n  name             String\n  sourceFormat     QuestionnaireSourceFormat @default(csv)\n  /// Free-form name of the requesting party (a customer, prospect, regulator).\n  requester        String?\n  vendorId         String?\n  dueDate          DateTime?\n  status           QuestionnaireStatus       @default(draft)\n  /// Headers from the *primary* sheet (the first sheet successfully\n  /// parsed), kept for backwards-compat display + CSV export. Multi-\n  /// sheet workbooks attach per-sheet headers to each `Question`.\n  headers          Json                      @default(\"[]\")\n  /// Storage key + metadata for the uploaded original file. We keep\n  /// the raw .xlsx / .docx blob in object storage so we can write\n  /// answers back into the customer's original workbook (preserving\n  /// styles, merged cells, branding, multi-sheet structure) instead\n  /// of reconstructing a fresh file.\n  originalFileKey  String?\n  originalFilename String?\n  originalMimeType String?\n  /// LLM-produced structural map of the uploaded workbook/document.\n  /// Describes each sheet/page (kind: metadata | instructions |\n  /// question_table | matrix), its column roles, header row, sub-\n  /// question relationships, and — critically — the exact A1 cell\n  /// coordinates where each answer must be written on export. Stored\n  /// verbatim so re-export is deterministic and we never re-run the\n  /// agent. Null for CSV imports (structure is implicit).\n  structureMap     Json?\n  /// Cover-page / metadata facts extracted by the structure agent —\n  /// e.g. {\"Company Name\": \"Acme\", \"Service Provided\": \"...\"}. Used\n  /// (a) as additional grounding for the answering agent and (b)\n  /// re-emitted to their original cells on export. Null for CSV.\n  metadataFacts    Json?\n  importedById     String\n  createdAt        DateTime                  @default(now())\n  updatedAt        DateTime                  @updatedAt\n\n  tenant     Tenant                   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  importedBy User                     @relation(\"QuestionnaireImporter\", fields: [importedById], references: [id])\n  vendor     Vendor?                  @relation(fields: [vendorId], references: [id])\n  questions  Question[]\n  answers    Answer[]\n  importJobs QuestionnaireImportJob[]\n\n  @@index([tenantId])\n  @@index([tenantId, status])\n}\n\nmodel Question {\n  id                   String       @id @default(cuid())\n  tenantId             String\n  questionnaireId      String\n  /// 1-based position in the source file. Used to preserve ordering on export.\n  sequenceNumber       Int\n  sectionTitle         String?\n  questionText         String       @db.Text\n  questionType         QuestionType @default(short_text)\n  /// JSON array of choice strings for multiple_choice / yes_no.\n  choices              Json         @default(\"[]\")\n  /// Verbatim row from the source file as parsed object — used to\n  /// rehydrate columns we don't model explicitly (control IDs, weights).\n  originalRow          Json         @default(\"{}\")\n  /// 0-based row index inside this question's source sheet (xlsx),\n  /// table (docx), or line in the file (csv). Used by the exporter\n  /// to drop the answer into the right cell.\n  sourceRowIndex       Int?\n  /// For xlsx round-trip: which sheet inside the workbook this row\n  /// belongs to. A workbook can have many sheets, each with its own\n  /// header row and answer column, so this is recorded per-question.\n  sourceSheetName      String?\n  /// For xlsx (and docx tables): 0-based index of the header row\n  /// inside this question's source sheet/table. Different sheets in\n  /// the same workbook can have headers at different rows.\n  sourceHeaderRowIndex Int?\n  /// Header text of the column that takes the answer on export, for\n  /// THIS question's source sheet/table. Stored per-question because\n  /// different sheets/tables in the same workbook may use different\n  /// answer column names (\"Response\", \"Answer\", \"Yes/No\"). Null when\n  /// no answer column was detected — the writer appends one.\n  answerColumnHeader   String?\n  /// For docx round-trip: 0-based index of the <w:tbl> inside\n  /// `word/document.xml` this row belongs to. A document can hold\n  /// many question tables; each question knows its own. Null for\n  /// xlsx/csv.\n  sourceTableIndex     Int?\n  /// Exact A1-style cell reference (e.g. \"F12\") inside the source\n  /// sheet/table where this question's answer must be written on\n  /// export. Produced by the structure agent at import time — the\n  /// writer just sets this cell, no header lookup needed. Supersedes\n  /// the legacy (sourceRowIndex + answerColumnHeader) lookup; old\n  /// fields are retained for backward compatibility with imports\n  /// that pre-date the structure agent.\n  answerCellA1         String?\n  /// Self-reference to the parent question for nested sub-questions\n  /// like \"a) Has this policy been communicated?\" under a top-level\n  /// control question. The UI nests sub-questions under their parent;\n  /// the answering agent gets the parent text as additional context.\n  parentQuestionId     String?\n  /// Structured contextual labels that frame this question — domain,\n  /// sub-domain, control id, evidence requirement, matrix column\n  /// label (the entity / system / process this cell asks about), etc.\n  /// The UI renders these as chips above the question; the answering\n  /// agent uses them as context.\n  /// Shape is intentionally open: { domain?: string; subDomain?:\n  /// string; controlId?: string; evidence?: string; column?: string;\n  /// [k: string]: string | undefined }.\n  contextLabels        Json?\n  createdAt            DateTime     @default(now())\n\n  tenant        Tenant        @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  questionnaire Questionnaire @relation(fields: [questionnaireId], references: [id], onDelete: Cascade)\n  answers       Answer[]\n  parent        Question?     @relation(\"QuestionChildren\", fields: [parentQuestionId], references: [id], onDelete: SetNull)\n  children      Question[]    @relation(\"QuestionChildren\")\n\n  @@index([tenantId])\n  @@index([questionnaireId])\n  @@index([questionnaireId, sequenceNumber])\n  @@index([parentQuestionId])\n}\n\nmodel Answer {\n  id              String       @id @default(cuid())\n  tenantId        String\n  questionnaireId String\n  questionId      String       @unique\n  content         String       @db.Text\n  status          AnswerStatus @default(pending)\n  generatedByAi   Boolean      @default(false)\n  /// Bounded [0,1]; absent for human-authored answers.\n  aiConfidence    Float?\n  /// Free-form citations: which policy IDs / control IDs / context rows\n  /// the AI cited as evidence. Helps reviewers verify quickly.\n  aiSources       Json         @default(\"[]\")\n  aiModel         String?\n  aiPrompt        String?      @db.Text\n  reviewedById    String?\n  reviewedAt      DateTime?\n  createdAt       DateTime     @default(now())\n  updatedAt       DateTime     @updatedAt\n\n  tenant        Tenant        @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  questionnaire Questionnaire @relation(fields: [questionnaireId], references: [id], onDelete: Cascade)\n  question      Question      @relation(fields: [questionId], references: [id], onDelete: Cascade)\n  reviewedBy    User?         @relation(\"AnswerReviewer\", fields: [reviewedById], references: [id])\n\n  @@index([tenantId])\n  @@index([questionnaireId])\n  @@index([questionnaireId, status])\n}\n\n// --- risk.prisma ---\nenum RiskCategory {\n  operational\n  technical\n  compliance\n  strategic\n  financial\n  reputational\n  security\n  privacy\n  third_party\n  environmental\n}\n\nenum RiskStatus {\n  not_started\n  in_progress\n  done\n  archived\n}\n\nenum TreatmentStrategy {\n  mitigate\n  accept\n  transfer\n  avoid\n  control\n}\n\nenum TreatmentStatus {\n  planned\n  in_progress\n  completed\n  overdue\n  cancelled\n}\n\nenum ControlEffectiveness {\n  no_control\n  need_improvement\n  adequate\n  effective\n}\n\nenum ApprovalStatus {\n  yes\n  no\n  na\n  pending\n}\n\nenum ProbabilityLevel {\n  rare\n  unlikely\n  possible\n  likely\n  almost_certain\n}\n\nenum ImpactLevel {\n  negligible\n  low\n  moderate\n  high\n  catastrophic\n}\n\nenum RiskDepartment {\n  engineering\n  product\n  operations\n  finance\n  legal\n  human_resources\n  sales\n  marketing\n  customer_support\n  it\n  security\n  compliance\n  executive\n  other\n}\n\nmodel Risk {\n  id             String  @id @default(cuid())\n  tenantId       String\n  riskIdentifier String?\n\n  // Core fields\n  title                 String\n  description           String?\n  riskImpactDescription String?\n  category              RiskCategory    @default(operational)\n  businessProcess       String?\n  department            RiskDepartment?\n  status                RiskStatus      @default(not_started)\n\n  // Inherent risk — qualitative + numeric\n  probability      ProbabilityLevel?\n  probabilityScore Int               @default(1)\n  impact           ImpactLevel?\n  impactScore      Int               @default(1)\n  riskScore        Int               @default(1)\n\n  // Residual risk — qualitative + numeric\n  residualLikelihood      ProbabilityLevel?\n  residualLikelihoodScore Int?\n  residualImpact          ImpactLevel?\n  residualImpactScore     Int?\n  residualRiskScore       Int?\n\n  // Controls\n  controlDescription   String?\n  controlEffectiveness ControlEffectiveness?\n  treatmentStrategy    TreatmentStrategy?\n  treatmentRationale   String?\n\n  // Action plan\n  actionPlan      String?\n  actionOwnerId   String?\n  actionOwnerName String?\n  estStartDate    DateTime?\n  estEndDate      DateTime?\n\n  // Approvals\n  budgetApproval     ApprovalStatus?\n  managementApproval ApprovalStatus?\n\n  // Ownership\n  ownerId      String?\n  riskProperty String?\n  remarks      String?\n  tags         String[] @default([])\n\n  // Optional link to a Processing Activity (RoPA) — set when this risk\n  // arises from a specific GDPR processing activity, enabling cross-link\n  // navigation from the Privacy workspace.\n  processingActivityId String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tenant             Tenant              @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  owner              User?               @relation(\"RiskOwner\", fields: [ownerId], references: [id])\n  actionOwner        User?               @relation(\"RiskActionOwner\", fields: [actionOwnerId], references: [id])\n  processingActivity ProcessingActivity? @relation(fields: [processingActivityId], references: [id])\n  assessments        RiskAssessment[]\n  treatments         RiskTreatment[]\n  matrixChanges      RiskMatrixChange[]\n\n  @@unique([tenantId, riskIdentifier])\n  @@index([tenantId])\n  @@index([tenantId, status])\n  @@index([tenantId, category])\n}\n\nmodel RiskAssessment {\n  id                 String   @id @default(cuid())\n  riskId             String\n  tenantId           String\n  assessedById       String\n  inherentLikelihood Int\n  inherentImpact     Int\n  residualLikelihood Int\n  residualImpact     Int\n  notes              String?\n  assessedAt         DateTime @default(now())\n  createdAt          DateTime @default(now())\n\n  risk       Risk   @relation(fields: [riskId], references: [id], onDelete: Cascade)\n  tenant     Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  assessedBy User   @relation(\"RiskAssessor\", fields: [assessedById], references: [id])\n\n  @@index([tenantId])\n  @@index([riskId])\n}\n\nmodel RiskTreatment {\n  id            String            @id @default(cuid())\n  riskId        String\n  tenantId      String\n  strategy      TreatmentStrategy\n  title         String            @default(\"\")\n  description   String?\n  responsibleId String\n  dueDate       DateTime?\n  completedAt   DateTime?\n  status        TreatmentStatus   @default(planned)\n  createdAt     DateTime          @default(now())\n  updatedAt     DateTime          @updatedAt\n\n  risk        Risk   @relation(fields: [riskId], references: [id], onDelete: Cascade)\n  tenant      Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  responsible User   @relation(\"RiskTreatmentResponsible\", fields: [responsibleId], references: [id])\n\n  @@index([tenantId])\n  @@index([riskId])\n}\n\n/// Per-tenant configuration for which risk register fields are visible.\n/// Stored as a JSON array of field config objects.\nmodel RiskRegisterConfig {\n  id        String   @id @default(cuid())\n  tenantId  String   @unique\n  fields    Json\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n}\n\nenum RiskMatrixChangeKind {\n  inherent\n  residual\n}\n\n/// Audit trail for inherent / residual likelihood×impact matrix updates.\nmodel RiskMatrixChange {\n  id             String               @id @default(cuid())\n  riskId         String\n  tenantId       String\n  kind           RiskMatrixChangeKind\n  /// matrix | overview | assessment\n  source         String               @default(\"matrix\")\n  changedById    String\n  prevLikelihood Int?\n  prevImpact     Int?\n  prevScore      Int?\n  newLikelihood  Int\n  newImpact      Int\n  newScore       Int\n  createdAt      DateTime             @default(now())\n\n  risk      Risk   @relation(fields: [riskId], references: [id], onDelete: Cascade)\n  tenant    Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  changedBy User   @relation(\"RiskMatrixChangeAuthor\", fields: [changedById], references: [id])\n\n  @@index([tenantId])\n  @@index([riskId])\n  @@index([riskId, createdAt])\n}\n\n// --- task.prisma ---\nenum TaskType {\n  manual\n  automated\n  recurring\n}\n\nenum TaskStatus {\n  pending\n  in_progress\n  completed\n  overdue\n  cancelled\n}\n\nenum TaskPriority {\n  critical\n  high\n  medium\n  low\n}\n\nenum TaskFrequency {\n  once\n  daily\n  weekly\n  monthly\n  quarterly\n  annually\n}\n\nenum TaskSourceModule {\n  training\n  control\n  risk\n  evidence\n  vendor\n  asset\n  audit\n  policy\n  bcp\n  incident\n  // Privacy / GDPR program task sources.\n  dsar\n  data_breach\n  dpia\n  processing_activity\n}\n\nenum EvidenceStatus {\n  draft\n  pending_review\n  approved\n  rejected\n}\n\nmodel Task {\n  id           String            @id @default(cuid())\n  tenantId     String\n  title        String\n  description  String?\n  type         TaskType          @default(manual)\n  status       TaskStatus        @default(pending)\n  priority     TaskPriority      @default(medium)\n  assigneeId   String?\n  controlId    String?\n  sourceModule TaskSourceModule?\n  sourceId     String?\n  dueDate      DateTime?\n  completedAt  DateTime?\n  frequency    TaskFrequency?\n  nextDueDate  DateTime?\n  createdAt    DateTime          @default(now())\n  updatedAt    DateTime          @updatedAt\n\n  tenant   Tenant         @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  assignee User?          @relation(\"TaskAssignee\", fields: [assigneeId], references: [id])\n  control  Control?       @relation(fields: [controlId], references: [id])\n  evidence TaskEvidence[]\n\n  @@index([tenantId])\n  @@index([assigneeId])\n  @@index([sourceModule, sourceId])\n  @@index([status])\n  @@index([dueDate])\n}\n\nmodel TaskEvidence {\n  id            String         @id @default(cuid())\n  taskId        String\n  tenantId      String\n  title         String\n  description   String?\n  fileUrl       String?\n  sourceType    String\n  sourceId      String?\n  status        EvidenceStatus @default(draft)\n  submittedById String\n  approvedById  String?\n  approvedAt    DateTime?\n  expiresAt     DateTime?\n  createdAt     DateTime       @default(now())\n\n  task        Task   @relation(fields: [taskId], references: [id], onDelete: Cascade)\n  tenant      Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  submittedBy User   @relation(\"EvidenceSubmitter\", fields: [submittedById], references: [id])\n  approvedBy  User?  @relation(\"EvidenceApprover\", fields: [approvedById], references: [id])\n\n  @@index([tenantId])\n  @@index([taskId])\n}\n\n// --- tenant-context.prisma ---\n// ============================================================\n// Tenant Context — long-form Q&A captured from a tenant so AI features\n// (policy drafting, questionnaire answering, risk scoring, chat\n// assistant) can produce content that reads like the customer wrote it.\n//\n// Each row is a single fact about the tenant: company size, hosting\n// region, deployment process, data-handling commitment, etc. AI prompts\n// assemble the relevant subset by `category` rather than dumping the\n// full table — keeps token usage bounded.\n//\n// Was previously called `OrganizationContext`. The model was renamed\n// when the tenancy concept was made first-class; the product UI may\n// still call this \"Organisation Context\" — that is purely a label.\n//\n// Lifecycle additions (Phase 0 of the \"ongoing AI context\" plan):\n//   • `status` lifecycle so superseded facts stay queryable for\n//     history without polluting AI grounding.\n//   • `supersedesId` self-relation to chain \"we used to say X; now Y.\"\n//   • `provenance` JSON to capture where a row came from (wizard,\n//     pasted text, chat turn, integration event).\n//   • `confirmedAt`/`confirmedBy` so AI-inferred rows can be promoted\n//     by a human accept and the audit trail records who.\n//\n// `TenantContextProposal` is a staging table written by the extraction\n// pipeline. AI features NEVER read from it — only the review UI does.\n// Promotion from proposal to active context happens transactionally on\n// user accept.\n// ============================================================\n\nenum TenantContextCategory {\n  company\n  tech_stack\n  processes\n  data_handling\n  risk_appetite\n  team\n}\n\nenum TenantContextSource {\n  onboarding\n  inferred\n  manual\n}\n\n/// Lifecycle for a TenantContext row.\n///   • `active`     — eligible for AI grounding.\n///   • `superseded` — replaced by a newer row; preserved for history.\n///   • `archived`   — manually retired by the user.\nenum TenantContextStatus {\n  active\n  superseded\n  archived\n}\n\n/// Lifecycle for an extraction-pipeline proposal awaiting user review.\nenum TenantContextProposalStatus {\n  pending\n  accepted\n  rejected\n}\n\nmodel TenantContext {\n  id           String                @id @default(cuid())\n  tenantId     String\n  category     TenantContextCategory\n  question     String\n  answer       String                @db.Text\n  source       TenantContextSource   @default(manual)\n  /// 0..1; AI-inferred answers carry a confidence; user-supplied = 1.\n  confidence   Float                 @default(1.0)\n  /// Lifecycle status. Only `active` rows are read by AI features.\n  status       TenantContextStatus   @default(active)\n  /// When this row replaced an older one, the old row's id. Builds the\n  /// history chain — the wizard can render \"we used to be on us-east-1\"\n  /// under each current answer.\n  supersedesId String?\n  supersedes   TenantContext?        @relation(\"TenantContextHistory\", fields: [supersedesId], references: [id])\n  supersededBy TenantContext[]       @relation(\"TenantContextHistory\")\n  /// Free-form provenance about where this row came from. Shape:\n  ///   { kind: \"wizard\"|\"paste\"|\"chat\"|\"integration\", ref?: string,\n  ///     proposalId?: string, conversationId?: string }\n  provenance   Json?\n  /// User confirmed an AI-inferred row is correct. NULL for rows that\n  /// didn't go through review (manual wizard answers default to\n  /// confirmed at creation time via the API).\n  confirmedAt  DateTime?\n  confirmedBy  String?\n  /// Bumped by AI features when this row is included in a prompt — lets\n  /// us prune stale facts from the wizard view (\"you haven't reviewed\n  /// these in 6 months\").\n  lastUsedAt   DateTime?\n  createdAt    DateTime              @default(now())\n  updatedAt    DateTime              @updatedAt\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId])\n  @@index([tenantId, status])\n  @@index([tenantId, category, status])\n  @@index([lastUsedAt])\n}\n\n/// Staging row for an AI-extracted context proposal. Written by the\n/// extraction pipeline (paste-to-extract, chat turns, future integrations)\n/// and reviewed via /settings/ai-context. Acceptance creates a\n/// `TenantContext` row in the same transaction; rejection just updates\n/// `status`. Never read by AI feature handlers.\n///\n/// `paste` covers the textarea-based extraction; `chat` covers passive\n/// capture during a /chat turn; future kinds (e.g. integration sync)\n/// plug in here.\nenum TenantContextProposalKind {\n  paste\n  chat\n  inferred\n}\n\nmodel TenantContextProposal {\n  id                  String                      @id @default(cuid())\n  tenantId            String\n  kind                TenantContextProposalKind   @default(paste)\n  category            TenantContextCategory\n  question            String\n  answer              String                      @db.Text\n  /// 0..1 confidence the extractor assigned to this proposal.\n  confidence          Float                       @default(0.5)\n  /// One-sentence rationale shown in the review card so reviewers\n  /// understand WHY the model proposed this.\n  rationale           String?                     @db.Text\n  /// Same shape as TenantContext.provenance.\n  provenance          Json?\n  /// When the model believes this proposal updates an existing row\n  /// (e.g. \"we moved AWS regions\"), the id of that row. On accept,\n  /// the linked row is marked `superseded` and the new row links\n  /// back via `supersedesId`.\n  supersedesContextId String?\n  status              TenantContextProposalStatus @default(pending)\n  decidedAt           DateTime?\n  decidedBy           String?\n  createdAt           DateTime                    @default(now())\n  updatedAt           DateTime                    @updatedAt\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId])\n  @@index([tenantId, status])\n  @@index([tenantId, createdAt])\n}\n\n// --- tenant.prisma ---\n// A `Tenant` represents a paying customer organisation. Was previously\n// called `Organization`; the rename moved every domain table's foreign\n// key column from `organizationId` to `tenantId` so the multi-tenant\n// concept is consistent across the whole stack. The product UI may\n// still surface the word \"Organisation\" — that is purely a label.\n\nenum TenantPlan {\n  free\n  starter\n  professional\n  enterprise\n}\n\nenum TenantStatus {\n  active\n  suspended\n  cancelled\n}\n\n// Controls how aggressive the collector should be when binding an\n// integration to tenant Controls on connect.\n//\n//   auto    — Persist IntegrationCheckControl rows immediately with\n//             isEnabled=true. Evidence flows as soon as the next\n//             collection job runs.\n//   suggest — Persist rows with isEnabled=false +\n//             disabledReason=pending_confirmation so the UI can show a\n//             preview (\"Connecting GitHub will contribute to 12\n//             controls\"). User confirms via\n//             POST /connections/:id/bindings/confirm to flip them on.\n//   off     — Don't bind at all; the user wires controls manually.\n//\n// Default is `suggest` to keep auditor scrutiny in the loop while\n// still showing the unified preview UX.\nenum IntegrationAutoBindMode {\n  auto\n  suggest\n  off\n}\n\nmodel Tenant {\n  id                      String                  @id @default(cuid())\n  name                    String\n  slug                    String                  @unique\n  plan                    TenantPlan              @default(free)\n  status                  TenantStatus            @default(active)\n  integrationAutoBindMode IntegrationAutoBindMode @default(suggest)\n  createdAt               DateTime                @default(now())\n  updatedAt               DateTime                @updatedAt\n\n  settings                      TenantSettings?\n  memberships                   Membership[]\n  frameworkInstances            FrameworkInstance[]\n  controls                      Control[]\n  policies                      Policy[]\n  policyAcks                    PolicyAcknowledgment[]\n  risks                         Risk[]\n  riskAssessments               RiskAssessment[]\n  riskTreatments                RiskTreatment[]\n  riskRegisterConfig            RiskRegisterConfig?\n  riskMatrixChanges             RiskMatrixChange[]\n  vendors                       Vendor[]\n  vendorAssessments             VendorAssessment[]\n  vendorResearches              VendorResearch[]\n  vendorDocuments               VendorDocument[]\n  assets                        Asset[]\n  incidents                     Incident[]\n  incidentTimelines             IncidentTimeline[]\n  audits                        Audit[]\n  auditDocuments                AuditDocument[]\n  auditFindings                 AuditFinding[]\n  bcps                          BusinessContinuityPlan[]\n  bias                          BusinessImpactAnalysis[]\n  bcpExercises                  BCPExercise[]\n  aiSystems                     AISystem[]\n  aiRiskAssessments             AIRiskAssessment[]\n  aiImpactAssessments           AIImpactAssessment[]\n  aiIncidents                   AIIncident[]\n  tasks                         Task[]\n  taskEvidence                  TaskEvidence[]\n  trainingPrograms              TrainingProgram[]\n  trainingCompletions           TrainingCompletion[]\n  trainingQuizzes               TrainingQuiz[]\n  quizAttempts                  QuizAttempt[]\n  aiProviderConfigs             AIProviderConfig[]\n  aiFeatureConfigs              AIFeatureConfig[]\n  trustCenterConfig             TrustCenterConfig?\n  trustResources                TrustResource[]\n  accessRequests                TrustCenterAccessRequest[]\n  trustCenterSnapshots          TrustCenterSnapshot[]\n  trustCenterEvents             TrustCenterEvent[]\n  controlRequirementAssignments ControlRequirementAssignment[]\n  evidence                      Evidence[]\n  policyControls                PolicyControl[]\n  policyComments                PolicyComment[]\n  vulnerabilities               Vulnerability[]\n  processingActivities          ProcessingActivity[]\n  dpias                         DPIA[]\n  dataBreaches                  DataBreach[]\n  dsarRequests                  DSARRequest[]\n  contextEntries                TenantContext[]\n  contextProposals              TenantContextProposal[]\n  conversations                 Conversation[]\n  conversationMessages          Message[]\n  questionnaires                Questionnaire[]\n  questions                     Question[]\n  answers                       Answer[]\n  questionnaireImportJobs       QuestionnaireImportJob[]\n  controlWeaknesses             ControlWeakness[]\n  directorySyncConfigs          DirectorySyncConfig[]\n  directorySyncRuns             DirectorySyncRun[]\n  externalIdentityMappings      ExternalIdentityMapping[]\n  // EE: managed LiteLLM routing + metered billing. See\n  // prisma/schema/billing.ee.prisma.\n  billingConfig                 TenantBillingConfig?\n  litellmKey                    TenantLiteLLMKey?\n  creditWallet                  CreditWallet?\n}\n\nmodel TenantSettings {\n  id          String   @id @default(cuid())\n  tenantId    String   @unique\n  companySize String?\n  industry    String?\n  country     String?\n  timezone    String?\n  logoUrl     String?\n  defaults    Json?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId])\n}\n\n// --- training.prisma ---\nenum TrainingType {\n  security_awareness\n  compliance\n  phishing_simulation\n  custom\n}\n\nenum TrainingFrequency {\n  once\n  monthly\n  quarterly\n  annually\n}\n\nenum TrainingCompletionStatus {\n  assigned\n  in_progress\n  completed\n  overdue\n}\n\nenum QuizQuestionType {\n  multiple_choice\n  true_false\n  multi_select\n}\n\nmodel TrainingProgram {\n  id          String            @id @default(cuid())\n  tenantId    String\n  title       String\n  description String?\n  type        TrainingType\n  frequency   TrainingFrequency @default(annually)\n  isRequired  Boolean           @default(true)\n  content     String?\n  dueDate     DateTime?\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  tenant      Tenant               @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  completions TrainingCompletion[]\n  quizzes     TrainingQuiz[]\n\n  @@index([tenantId])\n}\n\nmodel TrainingCompletion {\n  id                String                   @id @default(cuid())\n  trainingProgramId String\n  userId            String\n  tenantId          String\n  status            TrainingCompletionStatus @default(assigned)\n  score             Int?\n  completedAt       DateTime?\n  assignedAt        DateTime                 @default(now())\n  createdAt         DateTime                 @default(now())\n\n  trainingProgram TrainingProgram @relation(fields: [trainingProgramId], references: [id], onDelete: Cascade)\n  user            User            @relation(fields: [userId], references: [id])\n  tenant          Tenant          @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId])\n  @@index([trainingProgramId])\n}\n\nmodel TrainingQuiz {\n  id                String   @id @default(cuid())\n  trainingProgramId String\n  tenantId          String\n  title             String\n  description       String?\n  passingScore      Int      @default(70)\n  timeLimitMinutes  Int?\n  shuffleQuestions  Boolean  @default(false)\n  isPublished       Boolean  @default(false)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  trainingProgram TrainingProgram @relation(fields: [trainingProgramId], references: [id], onDelete: Cascade)\n  tenant          Tenant          @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  questions       QuizQuestion[]\n  attempts        QuizAttempt[]\n\n  @@index([tenantId])\n  @@index([trainingProgramId])\n}\n\nmodel QuizQuestion {\n  id        String           @id @default(cuid())\n  quizId    String\n  text      String\n  type      QuizQuestionType @default(multiple_choice)\n  sortOrder Int              @default(0)\n  points    Int              @default(1)\n  createdAt DateTime         @default(now())\n\n  quiz    TrainingQuiz @relation(fields: [quizId], references: [id], onDelete: Cascade)\n  options QuizOption[]\n  answers QuizAnswer[]\n\n  @@index([quizId])\n}\n\nmodel QuizOption {\n  id         String  @id @default(cuid())\n  questionId String\n  text       String\n  isCorrect  Boolean @default(false)\n  sortOrder  Int     @default(0)\n\n  question QuizQuestion @relation(fields: [questionId], references: [id], onDelete: Cascade)\n  answers  QuizAnswer[]\n\n  @@index([questionId])\n}\n\nmodel QuizAttempt {\n  id          String    @id @default(cuid())\n  quizId      String\n  userId      String\n  tenantId    String\n  score       Int?\n  totalPoints Int?\n  percentage  Int?\n  passed      Boolean?\n  startedAt   DateTime  @default(now())\n  completedAt DateTime?\n\n  quiz    TrainingQuiz @relation(fields: [quizId], references: [id], onDelete: Cascade)\n  user    User         @relation(fields: [userId], references: [id])\n  tenant  Tenant       @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  answers QuizAnswer[]\n\n  @@index([tenantId])\n  @@index([quizId])\n  @@index([userId])\n}\n\nmodel QuizAnswer {\n  id         String  @id @default(cuid())\n  attemptId  String\n  questionId String\n  optionId   String?\n  isCorrect  Boolean @default(false)\n\n  attempt  QuizAttempt  @relation(fields: [attemptId], references: [id], onDelete: Cascade)\n  question QuizQuestion @relation(fields: [questionId], references: [id], onDelete: Cascade)\n  option   QuizOption?  @relation(fields: [optionId], references: [id])\n\n  @@index([attemptId])\n}\n\n// --- trust-center.prisma ---\nenum TrustResourceType {\n  certificate\n  report\n  policy\n  attestation\n}\n\nenum TrustResourceGating {\n  public\n  contact_required\n  nda_required\n}\n\nenum AccessRequestStatus {\n  pending\n  approved\n  rejected\n}\n\n// Phase 2 (AI accelerators): controls how the public payload is built.\n// - `live`  — query the latest data on every (cached) request.\n// - `snapshot` — serve the most recent admin-published TrustCenterSnapshot.\n//   Useful for orgs that want a stable view between formal updates.\nenum TrustCenterPublicMode {\n  live\n  snapshot\n}\n\nmodel TrustCenterConfig {\n  id           String                @id @default(cuid())\n  tenantId     String                @unique\n  isEnabled    Boolean               @default(false)\n  customDomain String?\n  brandColor   String?\n  logoUrl      String?\n  description  String?\n  faqs         Json?\n  publicMode   TrustCenterPublicMode @default(live)\n  createdAt    DateTime              @default(now())\n  updatedAt    DateTime              @updatedAt\n\n  tenant    Tenant                @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  resources TrustResource[]\n  snapshots TrustCenterSnapshot[]\n  events    TrustCenterEvent[]\n\n  @@index([tenantId])\n}\n\n// A frozen copy of the public payload, captured by an admin via\n// \"Publish snapshot\". Only the most recent row per org is read by the\n// public surface when publicMode = 'snapshot'.\nmodel TrustCenterSnapshot {\n  id                  String   @id @default(cuid())\n  tenantId            String\n  trustCenterConfigId String\n  payload             Json\n  publishedById       String\n  createdAt           DateTime @default(now())\n\n  tenant            Tenant            @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  trustCenterConfig TrustCenterConfig @relation(fields: [trustCenterConfigId], references: [id], onDelete: Cascade)\n  publishedBy       User              @relation(\"TrustCenterSnapshotPublisher\", fields: [publishedById], references: [id])\n\n  @@index([tenantId, createdAt])\n  @@index([trustCenterConfigId])\n}\n\n// Lightweight visitor audit so admins can see what each prospect viewed.\n// Recorded by the public router on view + on resource interaction;\n// retained 90 days by a future cleanup job.\nenum TrustCenterEventType {\n  view\n  resource_view\n  resource_download\n  access_request\n}\n\nmodel TrustCenterEvent {\n  id                  String               @id @default(cuid())\n  tenantId            String\n  trustCenterConfigId String\n  type                TrustCenterEventType\n  resourceId          String?\n  visitorIp           String?\n  visitorUa           String?\n  visitorEmail        String?\n  metadata            Json?\n  createdAt           DateTime             @default(now())\n\n  tenant            Tenant            @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  trustCenterConfig TrustCenterConfig @relation(fields: [trustCenterConfigId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId, createdAt])\n  @@index([trustCenterConfigId, createdAt])\n  @@index([type, createdAt])\n}\n\nmodel TrustResource {\n  id                  String              @id @default(cuid())\n  tenantId            String\n  trustCenterConfigId String\n  title               String\n  description         String?\n  frameworkType       String?\n  resourceType        TrustResourceType\n  fileUrl             String\n  isPublic            Boolean             @default(false)\n  accessGating        TrustResourceGating @default(public)\n  createdAt           DateTime            @default(now())\n  updatedAt           DateTime            @updatedAt\n\n  tenant            Tenant                     @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  trustCenterConfig TrustCenterConfig          @relation(fields: [trustCenterConfigId], references: [id], onDelete: Cascade)\n  accessRequests    TrustCenterAccessRequest[]\n\n  @@index([tenantId])\n  @@index([trustCenterConfigId])\n}\n\nmodel TrustCenterAccessRequest {\n  id               String              @id @default(cuid())\n  tenantId         String\n  resourceId       String\n  requesterName    String\n  requesterEmail   String\n  requesterCompany String\n  requesterTitle   String?\n  reason           String?\n  status           AccessRequestStatus @default(pending)\n  ndaAccepted      Boolean             @default(false)\n  approvedById     String?\n  approvedAt       DateTime?\n  rejectedReason   String?\n  accessToken      String              @unique @default(cuid())\n  expiresAt        DateTime?\n  createdAt        DateTime            @default(now())\n  updatedAt        DateTime            @updatedAt\n\n  tenant     Tenant        @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  resource   TrustResource @relation(fields: [resourceId], references: [id], onDelete: Cascade)\n  approvedBy User?         @relation(\"AccessRequestApprover\", fields: [approvedById], references: [id])\n\n  @@index([tenantId])\n  @@index([accessToken])\n  @@index([requesterEmail, tenantId])\n  @@index([resourceId])\n}\n\n// --- user.prisma ---\nenum MembershipRole {\n  owner\n  admin\n  compliance_manager\n  auditor\n  viewer\n  integration_admin\n  // Data Protection Officer (GDPR Art. 37). Privacy-program-scoped role with\n  // read access across the platform and write access to privacy resources\n  // (RoPA, DPIAs, data-breach register, DSARs).\n  dpo\n}\n\nenum MembershipStatus {\n  active\n  invited\n  suspended\n}\n\nenum DirectorySyncProvider {\n  entra\n  google_workspace\n}\n\nenum DirectorySyncDefaultStatus {\n  active\n  invited\n}\n\nenum DirectorySyncRunStatus {\n  pending\n  running\n  succeeded\n  failed\n  cancelled\n}\n\nenum DirectorySyncRunTrigger {\n  schedule\n  manual\n}\n\nmodel User {\n  id            String    @id @default(cuid())\n  email         String    @unique\n  name          String\n  // Password hash is only populated when the active auth provider is a\n  // credential provider (e.g. local). It is null for users that authenticate\n  // via redirect providers (Cognito, OIDC, SAML, ...).\n  passwordHash  String?\n  // Identifier of the auth provider that owns this account. Must match the\n  // `id` returned by the provider plugin (e.g. \"local\", \"cognito\", or any\n  // third-party plugin id). Null only for users that have not yet completed\n  // first login (e.g. invited users on a redirect provider).\n  authProvider  String?\n  // Stable, opaque user identifier returned by the auth provider:\n  //   - local    : the user's email address\n  //   - cognito  : the user pool's `sub` claim\n  //   - <plugin> : provider-specific stable id\n  // Together with `authProvider`, this uniquely identifies the account.\n  externalId    String?\n  avatarUrl     String?\n  emailVerified Boolean   @default(false)\n  lastLoginAt   DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  memberships               Membership[]\n  ownedControls             Control[]                  @relation(\"ControlOwner\")\n  ownedPolicies             Policy[]                   @relation(\"PolicyOwner\")\n  createdPolicyVersions     PolicyVersion[]            @relation(\"PolicyVersionCreator\")\n  approvedPolicyVersions    PolicyVersion[]            @relation(\"PolicyVersionApprover\")\n  policyAcknowledgments     PolicyAcknowledgment[]\n  ownedRisks                Risk[]                     @relation(\"RiskOwner\")\n  actionOwnedRisks          Risk[]                     @relation(\"RiskActionOwner\")\n  riskAssessments           RiskAssessment[]           @relation(\"RiskAssessor\")\n  riskTreatments            RiskTreatment[]            @relation(\"RiskTreatmentResponsible\")\n  riskMatrixChanges         RiskMatrixChange[]         @relation(\"RiskMatrixChangeAuthor\")\n  vendorAssessments         VendorAssessment[]         @relation(\"VendorAssessor\")\n  vendorDocuments           VendorDocument[]           @relation(\"VendorDocUploader\")\n  ownedAssets               Asset[]                    @relation(\"AssetOwner\")\n  deletedAssets             Asset[]                    @relation(\"AssetDeletedBy\")\n  reportedIncidents         Incident[]                 @relation(\"IncidentReporter\")\n  assignedIncidents         Incident[]                 @relation(\"IncidentAssignee\")\n  incidentTimelineActions   IncidentTimeline[]\n  assignedAuditFindings     AuditFinding[]             @relation(\"AuditFindingAssignee\")\n  uploadedAuditDocuments    AuditDocument[]            @relation(\"AuditDocumentUploader\")\n  ownedBcps                 BusinessContinuityPlan[]   @relation(\"BCPOwner\")\n  ownedBias                 BusinessImpactAnalysis[]   @relation(\"BIAOwner\")\n  facilitatedBcpExercises   BCPExercise[]              @relation(\"BCPExerciseFacilitator\")\n  ownedAiSystems            AISystem[]                 @relation(\"AISystemOwner\")\n  aiRiskAssessments         AIRiskAssessment[]         @relation(\"AIRiskAssessor\")\n  aiRiskApprovals           AIRiskAssessment[]         @relation(\"AIRiskApprover\")\n  aiImpactAssessments       AIImpactAssessment[]       @relation(\"AIImpactAssessor\")\n  aiImpactApprovals         AIImpactAssessment[]       @relation(\"AIImpactApprover\")\n  reportedAiIncidents       AIIncident[]               @relation(\"AIIncidentReporter\")\n  assignedAiIncidents       AIIncident[]               @relation(\"AIIncidentAssignee\")\n  assignedTasks             Task[]                     @relation(\"TaskAssignee\")\n  submittedEvidence         TaskEvidence[]             @relation(\"EvidenceSubmitter\")\n  approvedEvidence          TaskEvidence[]             @relation(\"EvidenceApprover\")\n  submittedControlEvidence  Evidence[]                 @relation(\"EvidenceSubmittedBy\")\n  reviewedControlEvidence   Evidence[]                 @relation(\"EvidenceReviewedBy\")\n  trainingCompletions       TrainingCompletion[]\n  quizAttempts              QuizAttempt[]\n  policyComments            PolicyComment[]            @relation(\"PolicyCommentAuthor\")\n  resolvedComments          PolicyComment[]            @relation(\"PolicyCommentResolver\")\n  approvedAccessRequests    TrustCenterAccessRequest[] @relation(\"AccessRequestApprover\")\n  publishedTrustSnapshots   TrustCenterSnapshot[]      @relation(\"TrustCenterSnapshotPublisher\")\n  reportedVulnerabilities   Vulnerability[]            @relation(\"VulnReporter\")\n  assignedVulnerabilities   Vulnerability[]            @relation(\"VulnAssignee\")\n  ownedProcessingActivities ProcessingActivity[]       @relation(\"ProcessingActivityOwner\")\n  dpiaAssessments           DPIA[]                     @relation(\"DPIAAssessor\")\n  dpiaApprovals             DPIA[]                     @relation(\"DPIAApprover\")\n  reportedDataBreaches      DataBreach[]               @relation(\"DataBreachReporter\")\n  assignedDataBreaches      DataBreach[]               @relation(\"DataBreachAssignee\")\n  reportedControlWeaknesses ControlWeakness[]          @relation(\"ControlWeaknessReporter\")\n  assignedControlWeaknesses ControlWeakness[]          @relation(\"ControlWeaknessAssignee\")\n  assignedDsarRequests      DSARRequest[]              @relation(\"DSARAssignee\")\n  importedQuestionnaires    Questionnaire[]            @relation(\"QuestionnaireImporter\")\n  reviewedAnswers           Answer[]                   @relation(\"AnswerReviewer\")\n  questionnaireImportJobs   QuestionnaireImportJob[]   @relation(\"QuestionnaireImportJobCreator\")\n  externalIdentityMappings  ExternalIdentityMapping[]\n\n  @@unique([authProvider, externalId])\n  @@index([authProvider])\n}\n\nmodel Membership {\n  id          String           @id @default(cuid())\n  userId      String\n  tenantId    String\n  role        MembershipRole   @default(viewer)\n  permissions String[]\n  status      MembershipStatus @default(invited)\n  invitedAt   DateTime?\n  joinedAt    DateTime?\n  createdAt   DateTime         @default(now())\n  updatedAt   DateTime         @updatedAt\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, tenantId])\n  @@index([tenantId])\n  @@index([userId])\n}\n\nmodel DirectorySyncConfig {\n  id                   String                     @id @default(cuid())\n  tenantId             String\n  provider             DirectorySyncProvider\n  isEnabled            Boolean                    @default(true)\n  syncFrequencyMinutes Int                        @default(1440)\n  defaultRole          MembershipRole             @default(viewer)\n  defaultStatus        DirectorySyncDefaultStatus @default(invited)\n  groupRoleMappings    Json?\n  encryptedCredentials String                     @db.Text\n  lastSyncAt           DateTime?\n  lastSyncStatus       DirectorySyncRunStatus?\n  lastSyncError        String?\n  createdAt            DateTime                   @default(now())\n  updatedAt            DateTime                   @updatedAt\n\n  tenant   Tenant                    @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  runs     DirectorySyncRun[]\n  mappings ExternalIdentityMapping[]\n\n  @@unique([tenantId, provider])\n  @@index([tenantId])\n  @@index([tenantId, isEnabled])\n}\n\nmodel DirectorySyncRun {\n  id              String                  @id @default(cuid())\n  tenantId        String\n  configId        String\n  provider        DirectorySyncProvider\n  status          DirectorySyncRunStatus  @default(pending)\n  triggeredBy     DirectorySyncRunTrigger @default(schedule)\n  startedAt       DateTime?\n  finishedAt      DateTime?\n  usersDiscovered Int                     @default(0)\n  usersCreated    Int                     @default(0)\n  usersUpdated    Int                     @default(0)\n  usersSuspended  Int                     @default(0)\n  errorMessage    String?\n  createdAt       DateTime                @default(now())\n  updatedAt       DateTime                @updatedAt\n\n  tenant Tenant              @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  config DirectorySyncConfig @relation(fields: [configId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId, createdAt])\n  @@index([configId, status])\n}\n\nmodel ExternalIdentityMapping {\n  id                  String                @id @default(cuid())\n  tenantId            String\n  configId            String\n  provider            DirectorySyncProvider\n  externalId          String\n  userId              String\n  externalEmail       String\n  externalDisplayName String?\n  externalGroupIds    String[]\n  lastSeenAt          DateTime\n  createdAt           DateTime              @default(now())\n  updatedAt           DateTime              @updatedAt\n\n  tenant Tenant              @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  config DirectorySyncConfig @relation(fields: [configId], references: [id], onDelete: Cascade)\n  user   User                @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([tenantId, provider, externalId])\n  @@index([tenantId, provider, lastSeenAt])\n  @@index([userId, tenantId])\n}\n\n// --- vendor.prisma ---\nenum VendorRiskTier {\n  critical\n  high\n  medium\n  low\n}\n\nenum VendorStatus {\n  active\n  under_review\n  approved\n  rejected\n  offboarded\n}\n\nenum ResearchFrequency {\n  weekly\n  biweekly\n  monthly\n  yearly\n  none\n}\n\nenum ResearchStatus {\n  pending\n  in_progress\n  completed\n  failed\n}\n\nenum DpaStatus {\n  not_required\n  not_started\n  requested\n  received\n  approved\n  expired\n}\n\n// Global vendor catalog shared across all tenancies to avoid duplicate research\nmodel KnownVendor {\n  id               String    @id @default(cuid())\n  name             String\n  normalizedName   String    @unique\n  website          String?\n  description      String?\n  category         String?\n  logoUrl          String?\n  headquarters     String?\n  employeeRange    String?\n  foundedYear      Int?\n  industries       String[]\n  certifications   String[]\n  lastResearchedAt DateTime?\n  researchData     Json?\n  riskSummary      String?   @db.Text\n  overallScore     Int?\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  vendors    Vendor[]\n  researches VendorResearch[]\n\n  @@index([normalizedName])\n}\n\nmodel Vendor {\n  id                  String            @id @default(cuid())\n  tenantId            String\n  name                String\n  description         String?\n  website             String?\n  category            String?\n  riskTier            VendorRiskTier    @default(medium)\n  status              VendorStatus      @default(active)\n  dataProcessing      Boolean           @default(false)\n  isSubprocessor      Boolean           @default(false)\n  subprocessorPurpose String?\n  dataTypesShared     String[]\n  dataLocations       String[]\n  dpaStatus           DpaStatus         @default(not_required)\n  dpaExpiresAt        DateTime?\n  contractStartDate   DateTime?\n  contractEndDate     DateTime?\n  knownVendorId       String?\n  researchFrequency   ResearchFrequency @default(none)\n  lastResearchedAt    DateTime?\n  nextResearchAt      DateTime?\n  createdAt           DateTime          @default(now())\n  updatedAt           DateTime          @updatedAt\n\n  tenant               Tenant               @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  knownVendor          KnownVendor?         @relation(fields: [knownVendorId], references: [id])\n  assessments          VendorAssessment[]\n  contacts             VendorContact[]\n  researches           VendorResearch[]\n  documents            VendorDocument[]\n  // M:M link to GDPR Processing Activities for which this vendor processes\n  // personal data on the controller's behalf (Art. 28 sub-processor view).\n  processingActivities ProcessingActivity[] @relation(\"VendorProcessingActivities\")\n  questionnaires       Questionnaire[]\n\n  @@index([tenantId])\n  @@index([knownVendorId])\n  @@index([nextResearchAt])\n}\n\nmodel VendorAssessment {\n  id             String    @id @default(cuid())\n  vendorId       String\n  tenantId       String\n  assessedById   String\n  score          Int?\n  findings       String?\n  nextReviewDate DateTime?\n  researchId     String?\n  createdAt      DateTime  @default(now())\n\n  vendor     Vendor          @relation(fields: [vendorId], references: [id], onDelete: Cascade)\n  tenant     Tenant          @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  assessedBy User            @relation(\"VendorAssessor\", fields: [assessedById], references: [id])\n  research   VendorResearch? @relation(fields: [researchId], references: [id])\n\n  @@index([tenantId])\n  @@index([vendorId])\n  @@index([researchId])\n}\n\nmodel VendorResearch {\n  id            String         @id @default(cuid())\n  vendorId      String?\n  knownVendorId String?\n  tenantId      String?\n  status        ResearchStatus @default(pending)\n  researchType  String         @default(\"deep_research\")\n\n  overallScore    Int?\n  securityScore   Int?\n  complianceScore Int?\n  reputationScore Int?\n  financialScore  Int?\n\n  findings        Json?\n  summary         String? @db.Text\n  recommendations String? @db.Text\n  dataBreaches    Json?\n  certifications  Json?\n  rawData         Json?\n\n  startedAt    DateTime?\n  completedAt  DateTime?\n  errorMessage String?\n\n  createdAt DateTime @default(now())\n\n  vendor      Vendor?            @relation(fields: [vendorId], references: [id], onDelete: Cascade)\n  knownVendor KnownVendor?       @relation(fields: [knownVendorId], references: [id])\n  tenant      Tenant?            @relation(fields: [tenantId], references: [id])\n  assessments VendorAssessment[]\n\n  @@index([vendorId])\n  @@index([knownVendorId])\n  @@index([tenantId])\n  @@index([status])\n}\n\nmodel VendorContact {\n  id        String  @id @default(cuid())\n  vendorId  String\n  name      String\n  email     String?\n  role      String?\n  phone     String?\n  isPrimary Boolean @default(false)\n\n  vendor Vendor @relation(fields: [vendorId], references: [id], onDelete: Cascade)\n\n  @@index([vendorId])\n}\n\nenum VendorDocumentType {\n  agreement\n  nda\n  sla\n  dpa\n  sow\n  msa\n  insurance_certificate\n  security_assessment\n  compliance_report\n  other\n}\n\nmodel VendorDocument {\n  id           String             @id @default(cuid())\n  vendorId     String\n  tenantId     String\n  documentType VendorDocumentType @default(other)\n  title        String\n  description  String?\n  fileKey      String\n  fileName     String\n  fileSize     Int\n  mimeType     String\n  expiresAt    DateTime?\n  uploadedById String\n  createdAt    DateTime           @default(now())\n  updatedAt    DateTime           @updatedAt\n\n  vendor     Vendor @relation(fields: [vendorId], references: [id], onDelete: Cascade)\n  tenant     Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  uploadedBy User   @relation(\"VendorDocUploader\", fields: [uploadedById], references: [id])\n\n  @@index([vendorId])\n  @@index([tenantId])\n}\n\n// --- vulnerability.prisma ---\nenum VulnerabilitySeverity {\n  critical\n  high\n  medium\n  low\n  informational\n}\n\nenum VulnerabilityStatus {\n  open\n  confirmed\n  in_progress\n  remediated\n  accepted\n  false_positive\n}\n\nenum VulnerabilitySource {\n  scan\n  pentest\n  bug_bounty\n  manual\n  vendor_advisory\n}\n\nmodel Vulnerability {\n  id                String                @id @default(cuid())\n  tenantId          String\n  title             String\n  description       String?\n  severity          VulnerabilitySeverity\n  status            VulnerabilityStatus   @default(open)\n  source            VulnerabilitySource   @default(manual)\n  cvssScore         Float?\n  cveId             String?\n  cweId             String?\n  affectedComponent String?\n  productionImpact  Boolean               @default(false)\n  reportedById      String\n  assignedToId      String?\n  detectedAt        DateTime?\n  remediatedAt      DateTime?\n  createdAt         DateTime              @default(now())\n  updatedAt         DateTime              @updatedAt\n\n  tenant     Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  reportedBy User   @relation(\"VulnReporter\", fields: [reportedById], references: [id])\n  assignedTo User?  @relation(\"VulnAssignee\", fields: [assignedToId], references: [id])\n\n  @@index([tenantId])\n  @@index([tenantId, status])\n  @@index([tenantId, severity])\n}\n"
}

